import React from "react";
import styled from "styled-components";
import {NavLink} from "react-router-dom";
import {useTranslation} from "react-i18next";
import {GIFF_ICON, CASES_ICON, DOCUMENT_ICON} from "../../Utils/Constants";

const Wrapper = styled.div`
    position: fixed;
    top: 35vh;
    ${({$dir}) => ($dir === "ltr" ? "right: 0;" : "left: 0;")}
    width: fit-content;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.5vh;
    z-index: 1200;
    pointer-events: none;

    @media (max-width: 1200px) {
        top: 20vh;
    }
`;

const Item = styled.div`
    position: relative;
    display: flex;
    pointer-events: auto;
`;

const IconButton = styled.button`
    display: grid;
    place-items: center;
    width: 6vh;
    height: 6vh;
    border: 0;
    padding: 0;
    cursor: pointer;
    background: #33beb3;
    transition: background-color .2s ease;
    outline: none;

    &:hover {
        background: #354358;
    }

    img {
        width: 5vh;
        height: 5vh;
        display: block;
    }
`;

const Tooltip = styled.div`
    position: fixed;
    ${({$dir}) => ($dir === "ltr" ? "right: 3.1%;" : "left: 3.1%;")}
    width: 24vh;
    min-height: 6vh;
    padding: 0 1.2rem;
    background-color: #354358;
    display: grid;
    place-items: center;
    text-align: center;
    box-shadow: 0 10px 30px rgba(0, 0, 0, .25);
    z-index: 1300;
    pointer-events: auto;

    h5 {
        margin: 0;
        color: #fff;
        padding: 0;
        font-size: clamp(12px, 1.8vh, 16px);
        letter-spacing: .02em;
    }

    @media (max-width: 1200px) {
        ${({$dir}) => ($dir === "ltr" ? "right: 4%;" : "left: 4%;")}
    }

    @media (max-width: 678px) {
        ${({$dir}) => ($dir === "ltr" ? "right: 14%;" : "left: 14%;")}
        h5 {
            font-size: 2.5vh;
        }
    }
`;

const useIsTouch = () =>
    React.useMemo(
        () =>
            typeof window !== "undefined" &&
            window.matchMedia("(hover: none), (pointer: coarse)").matches,
        []
    );

const usePreload = (srcs = []) => {
    React.useEffect(() => {
        srcs.forEach((src) => {
            if (!src) return;
            const img = new Image();
            img.decoding = "async";
            img.loading = "eager";
            img.src = src;
        });
    }, [srcs]);
};

function PopItem({to, iconSrc, iconAlt, label, dir}) {
    const isTouch = useIsTouch();
    const [open, setOpen] = React.useState(false);
    const rootRef = React.useRef(null);

    React.useEffect(() => {
        if (!open) return;
        const close = (e) => {
            if (rootRef.current && !rootRef.current.contains(e.target)) {
                setOpen(false);
            }
        };
        const onScroll = () => setOpen(false);

        document.addEventListener("pointerdown", close, {capture: true});
        window.addEventListener("scroll", onScroll, {passive: true});
        return () => {
            document.removeEventListener("pointerdown", close, {capture: true});
            window.removeEventListener("scroll", onScroll);
        };
    }, [open]);

    const onPointerEnter = (e) => {
        if (!isTouch && e.pointerType === "mouse") setOpen(true);
    };
    const onPointerLeave = () => {
        if (!isTouch) setOpen(false);
    };

    const onIconClick = (e) => {
        if (!isTouch) return;
        if (!open) {
            e.preventDefault();
            e.stopPropagation();
            setOpen(true);
        }
    };

    return (
        <Item ref={rootRef} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave}>
            <IconButton type="button" aria-haspopup="true" aria-expanded={open} onClick={onIconClick}>
                <img src={iconSrc} alt={iconAlt} loading="eager" decoding="async"/>
            </IconButton>

            {open && (
                <Tooltip $dir={dir} role="tooltip" aria-hidden={!open}>
                    <NavLink to={to} target="_blank" style={{textDecoration: "none"}}>
                        <h5>{label}</h5>
                    </NavLink>
                </Tooltip>
            )}
        </Item>
    );
}

const AdvertisingPages = ({dir = "ltr"}) => {
    const {t} = useTranslation();
    const [isShown, setShown] = React.useState(false);

    usePreload([GIFF_ICON, CASES_ICON, DOCUMENT_ICON]);

    React.useEffect(() => {
        const id = setTimeout(() => setShown(true), 1200); // показываем чуть раньше
        return () => clearTimeout(id);
    }, []);

    if (!isShown) return <Wrapper $dir={dir}/>;

    return (
        <Wrapper $dir={dir}>
            <PopItem
                dir={dir}
                to="/promotion"
                iconSrc={GIFF_ICON}
                iconAlt="Our Gifts"
                label={t("advertising.pop_item_1")}
            />
            <PopItem
                dir={dir}
                to="/portfolio"
                iconSrc={CASES_ICON}
                iconAlt="Case Studies"
                label={t("advertising.pop_item_2")}
            />
            <PopItem
                dir={dir}
                to="/requisites"
                iconSrc={DOCUMENT_ICON}
                iconAlt="Company Details"
                label={t("advertising.pop_item_3")}
            />
        </Wrapper>
    );
};

export default AdvertisingPages;
