import React, {useState} from "react";
import styled, {keyframes} from "styled-components";
import PropTypes from "prop-types";
import {useTranslation} from "react-i18next";
import ShotSurveyModal from "../../Utils/ShotSurveyModal";

const pulse = keyframes`
    0% {
        transform: scale(1);
    }
    70% {
        transform: scale(1.03);
    }
    100% {
        transform: scale(1);
    }
`;

const Section = styled.section`
    width: 100%;
    padding: 1vh;
    margin-top: 15vh;
    display: grid;
    place-items: center;
    direction: ${({$dir}) => $dir};
`;

const Container = styled.div`
    width: min(1200px, 100%);
`;

const Head = styled.div`
    display: grid;
    margin-bottom: 28px;
`;

const Title = styled.h2`
    margin: 0;
    font-size: clamp(22px, 3vw, 36px);
    line-height: 1.2;
    letter-spacing: .3px;
`;

const Subtitle = styled.p`
    margin: 0;
    opacity: .8;
    font-size: clamp(14px, 1.4vw, 18px);
`;

const Grid = styled.div`
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: clamp(10px, 1vw, 16px);

    @media (max-width: 980px) {
        grid-template-columns: 1fr;
    }
`;

const Card = styled.article`
    background: #fff;
    box-shadow: 20px 20px 20px rgba(0, 0, 0, 0.06);
    padding: clamp(18px, 2.2vw, 28px);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    border: 1px solid rgba(0, 0, 0, .04);
    gap: 20px;
`;

const CardTitle = styled.h3`
    margin: 2px 0 0;
    font-size: clamp(18px, 2.2vw, 24px);
    letter-spacing: .2px;
    text-align: center;
    font-weight: 500;
`;

const List = styled.ul`
    margin: 0;
    padding: 0 0 0 1.2em;
    display: grid;
    gap: 8px;
    width: 100%;

    li {
        line-height: 1.45;
        font-size: clamp(14px, 1.4vw, 16px);
        text-align: start;
    }
`;

const Divider = styled.hr`
    border: none;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(0, 0, 0, .08), transparent);
    margin: 6px 0;
    width: 100%;
`;

const Foot = styled.div`
    display: flex;
    align-items: end;
    justify-content: space-between;
    flex-wrap: wrap;
    height: 15vh;
    width: 100%;
`;

const CtaRow = styled.div`
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    flex-wrap: wrap;
`;

const Button = styled.button`
    cursor: pointer;
    border: 1px solid ${({$variant}) => ($variant === "primary" ? "#33beb3" : "rgba(0,0,0,.14)")};
    background: ${({$variant}) => ($variant === "primary" ? "linear-gradient(180deg, #33beb3, #23a79f)" : "#fff")};
    color: ${({$variant}) => ($variant === "primary" ? "#fff" : "#125956")};
    padding: 12px 16px;
    letter-spacing: 0.6px;
    font-weight: 600;
    font-size: 14px;
    transition: transform .06s ease, box-shadow .2s ease, border-color .2s ease, background .2s ease;
    border-radius: 8px;

    &:hover {
        transform: translateY(-2px);
    }

    &:active {
        transform: translateY(0);
    }
`;

const Note = styled.p`
    margin: 0;
    font-size: 12px;
    opacity: .7;
`;

const Badge = styled.span`
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    padding: 10px 12px;
    border-radius: 12px;
    background: rgba(255, 186, 0, .14);
    border: 1px solid rgba(255, 186, 0, .35);
    animation: ${pulse} 2.4s ease-in-out infinite;
`;

export default function PromotionsSection({
                                              onEarlybird,
                                              onBrandingGift,
                                              onSeoBoost,
                                              onDetails,
                                              monthLabel,
                                              placesLeft = 5
                                          }) {
    const {t, i18n} = useTranslation();

    const dir = typeof i18n.dir === "function" ? i18n.dir() : (i18n.language === "he" ? "rtl" : "ltr");

    const title = t("promos.title", {month: monthLabel || t("promos.month_current")});
    const subtitle = t("promos.subtitle");
    const placesText = placesLeft > 0
        ? t("promos.badge.left", {count: placesLeft})
        : t("promos.badge.none");

    const [surveyOpen, setSurveyOpen] = useState(true);
    const [surveyPlan, setSurveyPlan] = useState(null);

    const openSurveyModal = (e) => {
        e.preventDefault();
        setSurveyOpen(true);
        if (!surveyPlan) setSurveyPlan("Standard");
    };

    return (
        <Section aria-labelledby="promo-title" $dir={dir}>
            <Container>
                <Head>
                    <Title id="promo-title">{title}</Title>
                    <Subtitle>{subtitle}</Subtitle>
                </Head>

                <Grid>
                    {/* Earlybird */}
                    <Card>
                        <CardTitle>{t("promos.cards.earlybird.title")}</CardTitle>

                        <List>
                            <li>{t("promos.cards.earlybird.points.0", {month: monthLabel || t("promos.month_current")})}</li>
                            <li>{t("promos.cards.earlybird.points.1")}</li>
                            <li>{t("promos.cards.earlybird.points.2")}</li>
                        </List>

                        <Divider/>

                        <Foot>
                            <Badge>⚡ {placesText}</Badge>
                            <CtaRow>
                                <Button $variant="primary" onClick={openSurveyModal}>
                                    {t("promos.cta.book")}
                                </Button>
                                {/*<Button $variant="ghost" onClick={onDetails}>*/}
                                {/*    {t("promos.cta.details")}*/}
                                {/*</Button>*/}
                            </CtaRow>
                        </Foot>
                    </Card>

                    {/* Branding Gift */}
                    <Card>
                        <CardTitle>{t("promos.cards.brandingGift.title")}</CardTitle>

                        <List>
                            <li>{t("promos.cards.brandingGift.points.0")}</li>
                            <li>{t("promos.cards.brandingGift.points.1")}</li>
                            <li>{t("promos.cards.brandingGift.points.2")}</li>
                        </List>

                        <Divider/>

                        <Foot>
                            <Note>{t("promos.cards.brandingGift.note")}</Note>
                            <CtaRow>
                                <Button $variant="primary" onClick={openSurveyModal}>
                                    {t("promos.cards.brandingGift.cta")}
                                </Button>
                            </CtaRow>
                        </Foot>
                    </Card>

                    {/* SEO Boost */}
                    <Card>
                        <CardTitle>{t("promos.cards.seoBoost.title")}</CardTitle>

                        <List>
                            <li>{t("promos.cards.seoBoost.points.0")}</li>
                            <li>{t("promos.cards.seoBoost.points.1")}</li>
                            <li>{t("promos.cards.seoBoost.points.2")}</li>
                        </List>

                        <Divider/>

                        <Foot>
                            <Note>{t("promos.cards.seoBoost.note")}</Note>
                            <CtaRow>
                                <Button $variant="primary"  onClick={openSurveyModal}>
                                    {t("promos.cards.seoBoost.cta")}
                                </Button>
                            </CtaRow>
                        </Foot>
                    </Card>
                </Grid>
            </Container>
            {surveyOpen && <ShotSurveyModal
                open={surveyOpen}
                plan={surveyPlan}
                dir={dir}
                onClose={() => setSurveyOpen(false)}
            />}
        </Section>
    );
}

PromotionsSection.propTypes = {
    onEarlybird: PropTypes.func,
    onBrandingGift: PropTypes.func,
    onSeoBoost: PropTypes.func,
    onDetails: PropTypes.func,
    monthLabel: PropTypes.string,
    placesLeft: PropTypes.number,
};
