import React from 'react';
import { successStories } from "../../Utils/Constants";
import SuccessStories from "./SuccessStories";
import styled from "styled-components";
import Arrows from "../../Utils/Arrows";
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/pagination';
import 'swiper/css/navigation';
import 'swiper/css/scrollbar';
import 'swiper/css/a11y';
import { useTranslation } from "react-i18next";
import { Navigation, Pagination } from "swiper/modules";

const SuccessStoriesWrapper = styled.div`
    padding-bottom: 5vh;
    margin: 0;
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: start;

    h1 {
        text-transform: uppercase;
        margin: 0;

    }

    @media screen and (max-width: 1030px) {
        padding: 2vh 0;
    }
`;

const SuccessStoriesWrapperSection = styled.div`
    margin-top: 1vh;
    width: 100%;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: center;
`;

const CoruselSwiper = styled(Swiper)`
    width: 90%;
    overflow: hidden;
    contain: content;

    @media (max-width: 1300px) {
        width: 100%;
    }
`;

const SuccessStoriesSlide = () => {
    const { t, i18n } = useTranslation();

    const dir = typeof i18n.dir === 'function'
        ? i18n.dir()
        : (i18n.language === 'he' ? 'rtl' : 'ltr');

    const stories = t('portfolio.successStories', { returnObjects: true }) || [];

    const slides = successStories.map((v, i) => (
        <SwiperSlide key={v.id}>
            <SuccessStories
                storyPic={v.pic}
                tag={v.tag}
                stack={v.stack}
                review={stories[i]?.review}
                storyTellerName={stories[i]?.name}
                storyTitle={stories[i]?.storyTitle}
                storyText={stories[i]?.storyText}
                detailsUrl={v.detailsUrl}
                demoUrl={v.demoUrl}
            />
        </SwiperSlide>
    ));

    return (
        <SuccessStoriesWrapper id="portfolio">
            <h1>{t('portfolio.title')}</h1>
            <SuccessStoriesWrapperSection>
                <CoruselSwiper
                    modules={[Pagination, Navigation]}
                    breakpoints={{
                        320: { slidesPerView: 1 },
                        800: { slidesPerView: 2 },
                        1200: { slidesPerView: 3 }
                    }}
                    spaceBetween={33}
                    navigation={true}
                    loop={true}
                    dir="ltr"
                    rtl={false}
                    key={dir}
                    resizeObserver={false}
                    observer={false}
                    observeParents={false}
                    updateOnWindowResize={false}
                    watchSlidesProgress={false}
                >
                    {slides}
                </CoruselSwiper>
            </SuccessStoriesWrapperSection>
            <Arrows />
        </SuccessStoriesWrapper>
    );
};

export default SuccessStoriesSlide;
