import React, {useMemo} from "react";
import styled from "styled-components";
import {useTranslation} from "react-i18next";
import PricingCart from "./PricingCart";

import {Swiper, SwiperSlide} from "swiper/react";
import {Navigation, A11y} from "swiper/modules";
import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/pagination";
import "swiper/css/a11y";

const isPromoActive = (promo) => {
    if (!promo?.price) return false;
    if (!promo?.until) return true;
    const [y, m, d] = String(promo.until).split("-").map(Number);
    const until = new Date(y, m - 1, d, 23, 59, 59, 999);
    return Date.now() <= until.getTime();
};

const Section = styled.section`
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #354358;
    padding: 64px 0;
    direction: ${(p) => (p.$rtl ? "rtl" : "ltr")};
`;

const Container = styled.div`
    width: 95vw;
    margin: 0 auto;
`;

const Title = styled.h2`
    font-size: clamp(28px, 3.2vw, 42px);
    font-weight: 800;
    margin: 0 0 28px 0;
    text-align: center;
    letter-spacing: 0.3px;
`;

const PricingSwiper = styled(Swiper)`
    width: 95%;
    margin: 0 auto;
    --swiper-pagination-color: ${({theme}) => theme?.colors?.accent || "#33beb3"};
    --swiper-navigation-color: ${({theme}) => theme?.colors?.accent || "#33beb3"};
    .swiper-button-prev,
    .swiper-button-next {
        display: none;
    }
    .swiper-wrapper {
        align-items: stretch;
    }

    .swiper-slide {
        display: flex;
        height: auto !important;
    }

    .slide-inner {
        display: flex;
        align-self: stretch;
        width: 100%;
    }

    .slide-inner > * {
        flex: 1 1 auto;
        width: 100%;
        min-height: 0;
    }

    @media (max-width: 1450px) {
        width: 100%;
        .swiper-button-prev,
        .swiper-button-next {
            display: flex;
        }
    }
`;

const Terms = styled.ul`
    margin: 3vh auto 0;
    padding: 0 12px 0 20px;
    max-width: 900px;
    color: #354358;
    line-height: 1.6;
    list-style-type: none;

    li + li {
        margin-top: 6px;
    }
`;

export default function PricingSection() {
    const {t, i18n} = useTranslation();
    const rtl = i18n.language?.startsWith("he");

    const plansObj = t("pricing.plans", {returnObjects: true}) || {};
    const baseOrder = ["lite", "starter", "standard"]; // без premium

    const plans = useMemo(() => {
        const arr = baseOrder
            .filter((key) => plansObj[key])
            .map((key) => {
                const p = plansObj[key];
                return {key, ...p, _hasPromo: isPromoActive(p?.promo)};
            });
        return arr;
    }, [plansObj]);

    const anyPromoActive = plans.some((p) => p._hasPromo);

    return (
        <Section $rtl={rtl} dir={rtl ? "rtl" : "ltr"} id="pricing">
            <Container>
                <Title as="h1">{t("pricing.title")}</Title>

                <PricingSwiper
                    modules={[Navigation, A11y]}
                    breakpoints={{
                        0: {slidesPerView: 1, spaceBetween: 16},
                        920: {slidesPerView: 2, spaceBetween: 24},
                        1450: {slidesPerView: 3, spaceBetween: 24}
                    }}
                    navigation
                    loop={false}
                    watchSlidesProgress
                    dir={rtl ? "rtl" : "ltr"}
                    key={rtl ? "rtl" : "ltr"}
                >
                    {plans.map((p) => {
                        const outlined = anyPromoActive ? p._hasPromo : p.key === "starter";
                        const featured = p._hasPromo;

                        return (
                            <SwiperSlide key={p.key}>
                                <div className="slide-inner">
                                    <PricingCart
                                        name={p.name}
                                        price={p.price}
                                        tagline={p.tagline}
                                        features={p.features}
                                        promo={p.promo}
                                        addonsTitle={p.addonsTitle}
                                        addons={p.addons}
                                        excludesTitle={p.excludesTitle}
                                        excludes={p.excludes}
                                        outlined={outlined}
                                        featured={featured}
                                        dir={rtl ? "rtl" : "ltr"}
                                        compact
                                    />
                                </div>
                            </SwiperSlide>
                        );
                    })}
                </PricingSwiper>

                <Terms>
                    {t("pricing.terms.vat") && <li>{t("pricing.terms.vat")}</li>}
                    {t("pricing.terms.payment") && <li>{t("pricing.terms.payment")}</li>}
                    {t("pricing.terms.overtime") && <li>{t("pricing.terms.overtime")}</li>}
                </Terms>
            </Container>
        </Section>
    );
}
