import React, {useState, useEffect} from "react";
import styled, {keyframes, css} from "styled-components";
import PropTypes from "prop-types";
import {useTranslation} from "react-i18next";
import {PORTFOLIOPIC} from "../../../Utils/Constants";
import ShotSurveyModal from "../../../Utils/ShotSurveyModal";

const pulseLines = keyframes`
    0% {
        transform: translateX(0);
        opacity: .25;
    }
    50% {
        transform: translateX(8px);
        opacity: .5;
    }
    100% {
        transform: translateX(0);
        opacity: .25;
    }
`;

const Wrapper = styled.section`
    width: 100%;
    margin-top: 70px;
    padding: clamp(20px, 4vw, 48px);
    background: #fcfdfb;
    position: relative;
    overflow: hidden;

    &:before, &:after {
        content: "";
        position: absolute;
        inset-inline-start: -20%;
        top: 10%;
        width: 140%;
        height: 2px;
        background: linear-gradient(90deg, rgba(18, 89, 86, .12), rgba(51, 190, 179, .12));
        animation: ${pulseLines} 4.8s ease-in-out infinite;
    }

    &:after {
        top: auto;
        bottom: 12%;
        animation-delay: .8s;
    }
`;

const Container = styled.div`
    width: min(1100px, 100%);
    margin-inline: auto;
    direction: ${({$dir}) => $dir};
`;

const Head = styled.header` margin-bottom: clamp(16px, 2.2vw, 28px); `;
const Title = styled.h2`
    font-size: clamp(24px, 3vw, 36px);
    line-height: 1.2;
    letter-spacing: .3px;
    color: #143a3a;
    margin: 0 0 6px;
`;
const Subtitle = styled.p`
    margin: 0;
    color: #3c5553;
    font-size: clamp(14px, 1.4vw, 16px);
`;

const SectionMain = styled.section`
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 2vw 0;
    
    @media (max-width: 978px) {
        flex-direction: column;
    }
`;
const Section = styled.section`
    background: #fff;
    padding: clamp(16px, 2.2vw, 24px);
    box-shadow: 0 18px 50px rgba(0, 0, 0, .06);
    width: fit-content;
    text-align: start;

    & + & {
        margin-top: clamp(16px, 1.8vw, 22px);
    }
`;
const SectionTitle = styled.h3`
    margin: 0 0 10px;
    font-size: clamp(18px, 2.2vw, 22px);
    color: #0f2f2e;
`;
const Paragraph = styled.p`
    margin: 8px 0;
    color: #2f3f3e;
    font-size: clamp(14px, 1.4vw, 16px);
`;
const RequirementsImg = styled.img`
    width: 40%;
    height: auto;
    box-shadow: 20px 20px 20px gray;
    margin: 0 2vw;
    @media (max-width: 978px) {
        width: 90%;
        margin: 2vh;
    }
`;


const CTA = styled.div`
    display: flex;
    gap: 10px;
    margin-top: 14px;
    flex-wrap: wrap;
    ${({$dir}) => $dir === "rtl" && css`justify-content: flex-end;`}
`;

const Button = styled.a`
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-top: 2vh;
    margin-inline-end: 1vw;
    padding: 8px 16px;
    border-radius: 25px;
    text-decoration: none;
    letter-spacing: 1px;
    font-weight: 600;
    transition: transform .15s ease, box-shadow .15s ease, background .2s ease, color .2s ease, border-color .2s ease;
    cursor: pointer;
    user-select: none;
    border: 0;

    ${({$variant}) => $variant === "primary"
            ? css`
                background: #33beb3;
                color: #fff;

                &:hover {
                    background: #354358;
                    color: #fff;
                }
            `
            : css`
                background: none;
                border: 1px solid #354358;
                color: #354358;

                &:hover {
                    color: #33beb3;
                    border-color: #33beb3;
                }

                &:active {
                    transform: translateY(0);
                }
            `}
`;

export default function CaseBlock({slug, contactPage, lang}) {
    const {t, i18n} = useTranslation();

    const activeLng = lang || i18n.language;
    const dir = typeof i18n.dir === "function" ? i18n.dir(activeLng) : (activeLng === "he" ? "rtl" : "ltr");

    const cases = t("cases_description", {returnObjects: true, lng: activeLng}) || [];
    const entry = cases.find((c) => c.slug === slug);

    const [surveyOpen, setSurveyOpen] = useState(true);
    const [surveyPlan, setSurveyPlan] = useState(null);

    useEffect(() => {
        if (!entry?.caseTariff) return;
        const tariff = String(entry.caseTariff).toLowerCase();
    }, [entry]);

    if (!entry) {
        return (
            <Wrapper>
                <Container $dir={dir}>
                    <Head><Title>{t("errors.caseNotFound", {
                        lng: activeLng,
                        defaultValue: "Case not found"
                    })}</Title></Head>
                    <Paragraph>{t("errors.checkSlug", {lng: activeLng, defaultValue: "Check slug:"})}
                        <code>{slug}</code></Paragraph>
                </Container>
            </Wrapper>
        );
    }

    const s1 = entry.sections?.[0]?.section_1 || {};
    const caseTitle = entry.caseTitle || "";

    const portfolio = PORTFOLIOPIC.find((c) => c.slug === slug) || {};
    const requirementsImg = portfolio.requirementsImages || "";
    const analysisImages = portfolio.analysisImages || "";
    const uiImg = portfolio.uiImg || "";

    const isObj = contactPage && typeof contactPage === "object";
    const secondaryHref = isObj ? contactPage.secondary : (contactPage || "");
    const targetBlank = isObj && contactPage.targetBlank ? "_blank" : undefined;
    const rel = targetBlank ? "noopener noreferrer" : undefined;

    const consultLabel = t("ui.consultBtn", {
        lng: activeLng,
        defaultValue: t("home.order_button", {lng: activeLng, defaultValue: "Start project" }),
    });
    const moreLabel = t("ui.moreBtn", {
        lng: activeLng,
        defaultValue: t("home_btn", {lng: activeLng, defaultValue: "Home"}),
    });

    const openSurveyModal = (e) => {
        e.preventDefault();
        setSurveyOpen(true);
        if (!surveyPlan) setSurveyPlan("Light");
    };

    return (
        <Wrapper>
            <Container $dir={dir}>
                <Head>
                    <Title>{caseTitle}</Title>
                    <Subtitle>{s1?.requirements?.title || ""}</Subtitle>
                </Head>

                {s1?.requirements && (
                    <SectionMain>
                        <Section>
                            <SectionTitle>{s1.requirements.title}</SectionTitle>
                            {s1.requirements.body?.map((text, i) => (
                                <Paragraph key={`req-${i}`}>{text}</Paragraph>
                            ))}
                        </Section>
                        {requirementsImg && <RequirementsImg src={requirementsImg} alt="requirements"/>}
                    </SectionMain>
                )}

                {s1?.analysis && (
                    <SectionMain>
                        {analysisImages && <RequirementsImg src={analysisImages} alt="analysis"/>}
                        <Section>
                            <SectionTitle>{s1.analysis.title}</SectionTitle>
                            {s1.analysis.body?.map((text, i) => (
                                <Paragraph key={`an-${i}`}>{text}</Paragraph>
                            ))}
                        </Section>
                    </SectionMain>
                )}

                {s1?.ux_ui && (
                    <SectionMain>
                        <Section>
                            <SectionTitle>{s1.ux_ui.title}</SectionTitle>
                            {s1.ux_ui.body?.map((text, i) => (
                                <Paragraph key={`ux-${i}`}>{text}</Paragraph>
                            ))}
                        </Section>
                        {uiImg && <RequirementsImg src={uiImg} alt="ui"/>}
                    </SectionMain>
                )}

                {s1?.conclusion && (
                    <Section>
                        <SectionTitle>{s1.conclusion.title}</SectionTitle>
                        {s1.conclusion.body?.map((text, i) => (
                            <Paragraph key={`conc-${i}`}>{text}</Paragraph>
                        ))}

                        <CTA $dir={dir}>
                            <Button
                                as="button"
                                type="button"
                                $variant="primary"
                                onClick={openSurveyModal}
                            >
                                {consultLabel}
                            </Button>
                            {secondaryHref && (
                                <Button href="/">
                                    {moreLabel}
                                </Button>
                            )}
                        </CTA>
                    </Section>
                )}
            </Container>

            {surveyOpen && <ShotSurveyModal
                open={surveyOpen}
                plan={surveyPlan}
                dir={dir}
                onClose={() => setSurveyOpen(false)}
            />}
        </Wrapper>
    );
}

CaseBlock.propTypes = {
    slug: PropTypes.string.isRequired,
    contactPage: PropTypes.oneOfType([
        PropTypes.string,
        PropTypes.shape({
            primary: PropTypes.string,
            secondary: PropTypes.string,
            targetBlank: PropTypes.bool,
        }),
    ]),
    lang: PropTypes.string,
};

CaseBlock.defaultProps = {
    contactPage: "",
    lang: undefined,
};
