import React from "react";
import styled from "styled-components";
import {useTranslation} from "react-i18next";

const Card = styled.article`
    display: flex;
    flex-direction: column;
    margin: 20px 20px 5vh 20px;
    justify-content: start;
    flex: 1 1 auto;
    background: transparent;
    min-height: 0;
    gap: 16px;
    padding: 22px 18px;

    color: ${({theme}) => theme.colors?.text ?? "#354358"};
    box-shadow: ${({$featured, $dir}) => $featured ? `${$dir === "rtl" ? "-15px" : "15px"} 15px 15px gray` : "none"};
    transition: border-color 0.2s ease,
    box-shadow .2s ease;
    @media (max-width: 968px) {
        box-shadow: none;
    }
    @media (max-width: 800px) {
        margin: 0;
    }
`;

const Header = styled.header`
    display: grid;
    gap: 6px;
`;

const PlanName = styled.p`
    font-weight: bold;
    margin: 0;
    font-size: 4vh;
    color: ${({theme}) => theme.colors?.heading ?? "#354358"};
`;

const Tagline = styled.p`
    margin: 12px 0;
    color: ${({theme}) => theme.colors?.muted ?? "#354358"};
    font-size: 2.5vh;
    line-height: 1.5;
    padding: 12px;
    border: 1px solid ${({theme}) => theme.colors?.heading ?? "#009688"};
    border-radius: 15px;
`;

const PriceWrap = styled.div`
    display: grid;
    gap: 6px;
    margin-top: 6px;
`;

const MainPrice = styled.div`
    font-size: 4vh;
    font-weight: 900;
    color: ${({theme}) => theme.colors?.heading ?? "#33beb3"};
`;

const PromoRing = styled.div`
    position: absolute;
    top: -4%;
    ${({$dir}) => $dir === "rtl" ? "left: 0;" : "right: 0;"};
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background-color: #009688;
    box-shadow: 0 5px 5px #009688 inset;
    animation: ring 3s infinite ease-out;
    z-index: 1;

    @keyframes ring {
        0% {
            transform: scale(0.8);
            opacity: 1;
        }
        70% {
            transform: scale(1.2);
            opacity: 0.8;
        }
        100% {
            transform: scale(1.2);
            opacity: 0;
        }
    }
`
const PromoRingTwo = styled.div`
    position: absolute;
    top: -5%;
    ${({$dir}) => $dir === "rtl" ? "left: 0;" : "right: 0;"};
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background-color: #009688;
    box-shadow: 0 5px 5px #009688 inset;
    animation: ring2 3s infinite ease-out;
    animation-delay: 0.5s;
    z-index: 0;

    @keyframes ring2 {
        0% {
            transform: scale(0.8);
            opacity: 1;
        }
        70% {
            transform: scale(1.15);
            opacity: 0.8;
        }
        100% {
            transform: scale(1.15);
            opacity: 0;
        }
    }
`
const PromoFloat = styled.div`
    position: absolute;
    justify-self: start;
    width: ${({$dir}) => $dir === "ltr" ? "70px" : "60px"};
    border-radius: 50%;
    height: 72px;
`
const PromoBadge = styled.span`
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    padding: 3px 15px;
    border-radius: 50%;
    width: 2.5rem;
    height: 4rem;
    background: ${({theme}) => theme.colors?.badge ?? "#009688"};
    color: ${({theme}) => theme.colors?.badgeText ?? "white"};
    animation: pulse 2s infinite ease-in-out;
    position: absolute;
    left: 0;
    right: 0;
    top:0;
    z-index: 10;


    @keyframes pulse {
        0% {
            transform: scale(1);
        }
        50% {
            transform: scale(1.05);
        }
        100% {
            transform: scale(1);
        }
    }
    @media (max-width: 478px) {
        font-size: 14px;
    }
`;

const Row = styled.div`
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
`;

const PromoPrice = styled.div`
    font-size: 28px;
    font-weight: 900;
    color: ${({theme}) => theme.colors?.accent ?? "#009688"};
    @media (max-width: 478px) {
        margin-inline-start: 25vw;
    }
`;

const OldPrice = styled.div`
    font-size: 20px;
    color: ${({theme}) => theme.colors?.muted2 ?? "#009688"};
    text-decoration: line-through;
`;

const SmallMuted = styled.div`
    font-size: 16px;
    font-weight: bold;
    color: ${({theme}) => theme.colors?.muted ?? "#354358"};
`;

const Block = styled.section`
    padding-top: 12px;
`;

const BlockTitle = styled.h4`
    font-size: 2vh;
    font-weight: 800;
    text-align: start;
    letter-spacing: .2px;
    text-transform: uppercase;
    padding: 0;
    color: ${({theme}) => theme.colors?.title ?? "#354358"};
`;

const List = styled.ul`
    margin: 0;
    text-align: start;
    padding-inline-start: 18px;
    color: ${({theme}) => theme.colors?.list ?? "#354358"};
    line-height: 1.5;

    li + li {
        margin-top: 2px;
    }
`;

const CTAGroup = styled.div`
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
    margin-top: auto;
    @media (min-width: 420px) {
        grid-template-columns: 1fr 1fr;
    }
`;

const PrimaryButton = styled.a`
    display: inline-grid;
    place-items: center;
    height: 42px;
    background: ${({theme}) => theme.colors?.accent ?? "#354358"};
    color: ${({theme}) => theme.colors?.accentOn ?? "#fff"};
    font-weight: 800;
    text-decoration: none;
    text-wrap: nowrap;
    padding: 5px 20px;
    transition: filter .15s ease;

    &:hover {
        background: ${({theme}) => theme.colors?.accent ?? "#009688"};
        color: ${({theme}) => theme.colors?.accentOn ?? "#fff"} !important;
    }
`;

const GhostButton = styled.a`
    display: inline-grid;
    place-items: center;
    height: 42px;
    border: 1.5px solid ${({theme}) => theme.colors?.ghostBorder ?? "#354358"};
    background: transparent;
    font-weight: bold;
    color: ${({theme}) => theme.colors?.ghostText ?? "#354358"};
    text-decoration: none;
    transition: background-color .15s ease;
    text-wrap: nowrap;
    padding: 5px 20px;

    &:hover {
        color: ${({theme}) => theme.colors?.ghostHover ?? "#009688"};
        border-color: ${({theme}) => theme.colors?.ghostHover ?? "#009688"};
    }
`;

const formatILS = (n) => typeof n === "number" ? n.toLocaleString("he-IL", {
    style: "currency",
    currency: "ILS",
    maximumFractionDigits: 0
}) : n;

const formatDate = (iso) => {
    try {
        const d = new Date(iso);
        const dd = String(d.getDate()).padStart(2, "0");
        const mm = String(d.getMonth() + 1).padStart(2, "0");
        const yyyy = d.getFullYear();
        return `${dd}.${mm}.${yyyy}`;
    } catch {
        return iso;
    }
};

const isPromoActive = (promo) => {
    if (!promo?.price) return false;
    if (!promo?.until) return true;
    const [y, m, d] = promo.until.split("-").map(Number);
    const until = new Date(y, m - 1, d, 23, 59, 59, 999);
    return Date.now() <= until.getTime();
};

function PricingCart({
                         name,
                         tagline,
                         price,
                         promo,
                         promoLabel,
                         promoPrice,
                         promoUntil,
                         features = [],
                         addonsTitle,
                         addons = [],
                         excludesTitle,
                         excludes = [],
                         featured = false,
                         whatsappHref = "https://wa.me/972547615507",
                         emailHref = "mailto:hexobee.dev@gmail.com",
                         whatsappText,
                         emailText,
                         dir,
                     }) {
    const {t} = useTranslation();

    const promoObj = promo ?? {label: promoLabel, price: promoPrice, until: promoUntil};
    const promoOk = isPromoActive(promoObj);

    const _price = typeof price === "number" ? formatILS(price) : price;
    const _promo = typeof promoObj?.price === "number" ? formatILS(promoObj.price) : promoObj?.price;

    return (<Card $featured={featured} $dir={dir}>
            <Header>
                <PlanName>{name}</PlanName>
                {tagline ? <Tagline>{tagline}</Tagline> : null}
            </Header>
            <PriceWrap>
                {promoOk ? (<>
                        {promoObj?.label ? <PromoFloat $dir={dir}><PromoRing
                            $dir={dir}/><PromoRingTwo $dir={dir}/>
                            <PromoBadge>
                                {promoObj.label}</PromoBadge></PromoFloat> : null}
                        <Row>
                            <PromoPrice>{_promo}</PromoPrice>
                            <OldPrice>{_price}</OldPrice>
                        </Row>
                        {promoObj?.until ? <SmallMuted>{t("pricing.promoUntilPrefix", "до")}
                            {formatDate(promoObj.until)}</SmallMuted> : null}
                    </>) : (<MainPrice>{_price}</MainPrice>)}
            </PriceWrap>

            {features?.length > 0 && (<Block>
                    <BlockTitle>{t("pricing.includedTitle", "Что входит")}</BlockTitle>
                    <List>{features.map((x, i) => <li key={`f-${i}`}>{x}</li>)}</List>
                </Block>)}

            {addons?.length > 0 && (<Block>
                    <BlockTitle>{addonsTitle || t("pricing.addonsTitle", "Дополнительно")}</BlockTitle>
                    <List>{addons.map((x, i) => <li key={`a-${i}`}>{x}</li>)}</List>
                </Block>)}

            {excludes?.length > 0 && (<Block>
                    <BlockTitle>{excludesTitle || t("pricing.excludesTitle", "Не входит")}</BlockTitle>
                    <List>{excludes.map((x, i) => <li key={`e-${i}`}>{x}</li>)}</List>
                </Block>)}

            {/* CTA */}
            <CTAGroup>
                <PrimaryButton href={whatsappHref} target="_blank" rel="noreferrer"
                               aria-label={whatsappText || t("pricing.cta.whatsapp")}>
                    {whatsappText || t("pricing.cta.whatsapp")}
                </PrimaryButton>
                <GhostButton href={emailHref}>
                    {emailText || t("pricing.cta.email")}
                </GhostButton>
            </CTAGroup>
        </Card>);
}

export default React.memo(PricingCart);

