import React, {useRef, useState} from 'react';
import styled from 'styled-components';
import ReadMore from "../../Utils/ReadMore/ReadMore";
import {useTranslation} from "react-i18next";
import * as emailjs from "@emailjs/browser";

const SuccessStoryWrapper = styled.div`
    display: flex;
    width: 100%;
    min-height: 100vh;
    margin: 30px 0;
    align-items: stretch;
    justify-content: start;
    box-shadow: 20px 20px 20px gray;
    overflow: hidden;
    contain: content;

    @media (max-width: 1030px) {
        box-shadow: none;

        @media (max-width: 678px) {
            min-height: auto;
        }
`;

const SuccessStorySection = styled.div`
    width: 100%;
    display: flex;
    align-items: start;
    justify-content: center;

    @media screen and (max-width: 978px) {
        flex-direction: column;
    }
`;

const VideoStory = styled.div`
    width: 100%;
    max-width: 1100px;
    margin-bottom: 4vh;
    border: 0.5px solid gainsboro;
    overflow: hidden;
    z-index: 1;
    object-fit: fill;

    video {
        width: 100%;
        height: 100%;
        display: block;
        object-fit: cover;
    }
`;

const CaseTag = styled.span`
    display: inline-block;
    background:  #354358;
    padding: 0.3rem 1rem;
    border-radius: 20px;
    font-size: 0.8rem;
    color: white;
    margin-inline-end: 1rem;
`;

const InfoSection = styled.div`
    display: flex;
    align-items: center;
    justify-content: center;
    gap: .75rem;

    .divider {
        padding: 0 0.25rem;
        font-weight: 400;
        color: #354358;
        font-size: 1.4rem;
        user-select: none;
    }
`;

const ReviewButton = styled.button`
    background: none;
    border: none;
    padding: 0 1rem;
    font-weight: 400;
    color: #354358;
    font-size: 1.1rem;
    cursor: pointer;
    text-decoration: underline;
    text-underline-offset: 3px;

    &:hover {
        color: #006e64;
    }
`;

const TechStack = styled.div`
    margin-top: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 0.6rem;
    margin-bottom: 1.5rem;

    @media (max-width: 978px) {
        padding: 1rem;
    }
`;

const TechItem = styled.span`
    border: 1px solid #009688;
    color: #354358;
    font-weight: 600;
    padding: 0.2rem 0.8rem;
    border-radius: 15px;
    font-size: 0.8rem;
`;

const TitleStory = styled.p`
    padding: 1rem 0;
    max-width: 70vw;
    font-size: 3vh;
    text-align: center;
    color: #354358;
    font-weight: bolder;
`;

const TitleSuccessStorySection = styled.div`
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
`;

const MainSection = styled.div`
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
`;

const TextStoryBox = styled.div`
    font-size: 2.5vh;
    width: min(70%, 900px);
    text-align: left;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 20vh;
`;
const TechSection = styled.div`
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    min-height: 17vh;
`
const ButtonGroup = styled.div`
    margin: 1rem 0;
    gap: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
`;

const LinkButton = styled.a`
    padding: 0.4rem 2rem;
    text-decoration: none;
    transition: all 0.3s;
    cursor: pointer;
    text-align: center;
    font-weight: bolder;
    display: inline-block;
`;

const ActionButton = styled.button`
    padding: 0.4rem 2rem;
    transition: all 0.3s;
    height: 4vh;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    text-align: center;
    font-weight: bolder;
    background: transparent;
    border: 1px solid #354358;
    color: #354358;
    border-radius: 0;
    letter-spacing: 1px;

    &:hover {
        border: 2px solid #009688;
        color: #009688;
    }
`;

const PrimaryLink = styled(LinkButton)`
    background: #009688;
    color: white !important;
    padding: 0.4rem 2rem;
    height: 4vh;
    display: flex;
    align-items: center;
    justify-content: center;
    
    &:hover {
        background: #354358;
    }
`;

const ModalOverlay = styled.div`
    position: fixed;
    inset: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 5000;
    backdrop-filter: blur(5px);
`;

const ModalContent = styled.div`
    background: white;
    width: 100vw;
    max-width: 400px;
    padding: 30px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
    position: relative;
`;

const ModalHeader = styled.div`
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 25px;
`;

const ModalTitle = styled.h3`
    margin: 0;
    font-size: 22px;
    color: #354358;
`;

const CloseButton = styled.button`
    background: none;
    border: none;
    font-size: 80px;
    cursor: pointer;
    color: #354358;
    padding: 0;
    line-height: 1;

    &:hover {
        color: #354358;
    }
`;

const Form = styled.form`
    display: flex;
    flex-direction: column;
    gap: 20px;
`;

const FormGroup = styled.div`
    display: flex;
    flex-direction: column;
    gap: 8px;
`;

const Label = styled.label`
    font-size: 14px;
    color: #354358;
    font-weight: 500;
`;

const Input = styled.input`
    padding: 12px 15px;
    border: 1px solid #dfe6e9;
    border-radius: 8px;
    font-size: 16px;
    transition: all 0.3s ease;

    &:focus {
        border-color: #33beb3;
        outline: none;
        box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.2);
    }
`;

const Textarea = styled.textarea`
    padding: 12px 15px;
    border: 1px solid #dfe6e9;
    border-radius: 8px;
    font-size: 16px;
    resize: vertical;
    min-height: 100px;
    transition: all 0.3s ease;

    &:focus {
        border-color: #33beb3;
        outline: none;
        box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.2);
    }
`;

const SubmitButton = styled.button`
    background: #33beb3;
    color: white;
    padding: 14px;
    border: none;
    font-weight: 600;
    font-size: 16px;
    cursor: pointer;
    transition: all 0.3s ease;
    border-radius: 7px;
    margin-top: 10px;
    letter-spacing: 2px;

    &:hover {
        background: #354358;
    }

    &:active {
        transform: scale(0.98);
    }
`;

const SuccessStories = (props) => {
    const {t} = useTranslation();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isReviewOpen, setIsReviewOpen] = useState(false);
    const form = useRef();

    const closeModalForm = () => {
        setTimeout(() => setIsModalOpen(false), 700);
    };

    const sendEmail = (e) => {
        e.preventDefault();
        emailjs
            .sendForm('service_h1vphxh', 'template_lewiula', form.current, {
                publicKey: 'jhCEXKdgNdbbtEUOy',
            })
            .then(
                () => {
                    e.target.reset();
                },
                (error) => {
                    console.log('FAILED...', error.text);
                },
            );
        closeModalForm();
    };

    return (
        <SuccessStoryWrapper>
            <SuccessStorySection>
                {isModalOpen && (
                    <ModalOverlay onClick={() => setIsModalOpen(false)}>
                        <ModalContent role="dialog" aria-modal="true"
                                      onClick={(e) => e.stopPropagation()}>
                            <ModalHeader>
                                <ModalTitle>{t('modal_form_order.title')}</ModalTitle>
                                <CloseButton aria-label="Close"
                                             onClick={() => setIsModalOpen(false)}>×</CloseButton>
                            </ModalHeader>

                            <Form ref={form} onSubmit={sendEmail}>
                                <input type="hidden" name="category" value="🔥Hochu tak!"/>
                                <input type="hidden" name="name_site" value={props.storyTitle}/>

                                <FormGroup>
                                    <Label>{t('modal_form_order.your_name')}</Label>
                                    <Input
                                        type="text"
                                        name="name"
                                        placeholder={t('modal_form_order.name_placeholder')}
                                        required
                                    />
                                </FormGroup>

                                <FormGroup>
                                    <Label>{t('modal_form_order.mail')}</Label>
                                    <Input
                                        type="email"
                                        name="email"
                                        placeholder={t('modal_form_order.mail_placeholder')}
                                        required
                                    />
                                </FormGroup>

                                <FormGroup>
                                    <Label>{t('modal_form_order.wishes')}</Label>
                                    <Textarea
                                        name="message"
                                        placeholder={`${t('modal_form_order.wishes_placeholder')}`}
                                        rows={4}
                                    />
                                </FormGroup>

                                <SubmitButton type="submit">
                                    {t('modal_form_order.button')}
                                </SubmitButton>
                            </Form>
                        </ModalContent>
                    </ModalOverlay>
                )}

                <MainSection>
                    <VideoStory>
                        <video
                            autoPlay
                            muted
                            playsInline
                            loop
                            controls
                            preload="metadata"
                        >
                            <source src={props.storyPic} type="video/mp4"/>
                        </video>
                    </VideoStory>

                    <InfoSection>
                        <CaseTag>{props.tag}</CaseTag>
                        <span className="divider">/</span>
                        <ReviewButton type="button" onClick={() => setIsReviewOpen(true)} aria-haspopup="dialog">
                            {t('review_title')}
                        </ReviewButton>
                    </InfoSection>

                    <TitleSuccessStorySection>
                        <TitleStory>{props.storyTitle}</TitleStory>
                    </TitleSuccessStorySection>
                    <TextStoryBox>
                        <ReadMore text={props.storyText}/>
                    </TextStoryBox>
                    <TechSection>
                        <ButtonGroup>
                            <PrimaryLink
                                href={props.demoUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                aria-label={t('portfolio.demo')}
                            >
                                {t('portfolio.demo')}
                            </PrimaryLink>

                            <ActionButton type="button" onClick={() => setIsModalOpen(true)}>
                                {t('portfolio.want')}
                            </ActionButton>
                        </ButtonGroup>
                        <TechStack>
                            {props.stack.map((tech, index) => (
                                <TechItem key={index}>{tech}</TechItem>
                            ))}
                        </TechStack>
                    </TechSection>
                    {isReviewOpen && (
                        <ModalOverlay onClick={() => setIsReviewOpen(false)}>
                            <ModalContent role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}>
                                <ModalHeader>
                                    <ModalTitle>{props.review}</ModalTitle>
                                    <CloseButton aria-label="Close"
                                                 onClick={() => setIsReviewOpen(false)}>×</CloseButton>
                                </ModalHeader>
                            </ModalContent>
                        </ModalOverlay>
                    )}
                </MainSection>
            </SuccessStorySection>
        </SuccessStoryWrapper>
    );
};

export default SuccessStories;
