import React from 'react';
import styled from 'styled-components';
import SuccessStoriesSlide from "./SuccessStoriesSlide";
import ContentOfTheProgram from "./ContentOfTheProgram";
import {useTranslation} from "react-i18next";
import PricingSection from "../Pricing/PricingSection";
import LogoShowcase from "../LogoShowcase/LogoShowcase";

const AboutWrapper = styled.div`
    width: 100%;
    height: auto;
    display: flex;
    flex-direction: column;
    align-items: end;
    justify-content: start;
    background-color: transparent;

    @media (max-width: 1230px) {
        margin-top: 7dvh;
    }
`;

const AboutMission = styled.div`
    width: 75vw;
    padding: 0 2vw;

    h1 {
        color: #354358;
        margin-bottom: 30px;
    }

    h3 {
        font-weight: bold;
        color: #354358;
    }

    h2 {
        padding: 2vw;
    }

    p {
        padding: 0 3vw;
        text-align: justify;
    }

    img {
        margin-top: 2vw;;
        width: 17rem;
        height: 18rem;
    }
;
    @media (max-width: 1300px) {
        width: 100%;
        flex-direction: column;
        p {
            padding: 2vw 6vw;
        }
    }
    @media (max-width: 478px) {
        margin-bottom: 3vh;
    }

`;
const TextAbout = styled.div`
    width: 100%;
    margin-top: 30px;
`
const About = () => {
    const {t} = useTranslation();
    return (
        <AboutWrapper>
            <SuccessStoriesSlide/>
            <LogoShowcase/>
            <AboutMission id="about">
                <TextAbout>
                    <h1>{t('about.title')}</h1>
                    <h2>{t('about.text_1')}</h2>
                    <p>{t('about.text_3')}</p>
                    <p>{t('about.text_1.1')}</p>
                    <p>{t('about.text_2')}</p>
                </TextAbout>
            </AboutMission>
            <PricingSection/>
            <ContentOfTheProgram/>
        </AboutWrapper>
    );
};

export default About;