import React from 'react';
import { Route, Routes } from "react-router-dom";
import Home from "./Home/Home";
import SurveyFormHebrew from "./SurveyForm/SurveyFormHebrew";
import SurveyFormEng from "./SurveyForm/SurveyFormEng";
import SurveyFormRus from "./SurveyForm/SurveyFormRus";
import NotFound404 from "./NotFound404";
import PromotionsSection from "./PromotionsSection/PromotionsSection";
import RequisitesPage from "./PromotionsSection/RequisitesPage";
import PortfolioCases from "./PromotionsSection/CaseBlocks/PortfolioCases";
import {PORTFOLIOPIC} from "../Utils/Constants";
import CaseBlock from "./PromotionsSection/CaseBlocks/CaseBlock";

const Main = (props) => {
    const { dir, changeLanguage, currentLang } = props;

    const lang = (currentLang || "en").toString().slice(0,2).toLowerCase();

    const addressCases = PORTFOLIOPIC.map((item) => (
        <Route
            key={item.slug}
            path={`/${item.slug}`}
            element={
                <CaseBlock
                    slug={item.slug}
                    lang={lang}
                    contactPage="/contacts"
                />
            }
        />
    ));

    return (
        <Routes>
            <Route
                path="/"
                element={<Home dir={dir} changeLanguage={changeLanguage} currentLang={currentLang} />}
            />
            <Route
                path="/home"
                element={<Home dir={dir} changeLanguage={changeLanguage} currentLang={currentLang} />}
            />
            <Route
                path="/survey-form-eng"
                element={<SurveyFormEng currentLang={currentLang} />}
            />
            <Route
                path="/survey-form-he"
                element={<SurveyFormHebrew currentLang={currentLang} />}
            />
            <Route
                path="/survey-form-ru"
                element={<SurveyFormRus currentLang={currentLang} />}
            />
            <Route
                path="/promotion"
                element={<PromotionsSection dir={dir} changeLanguage={changeLanguage} currentLang={currentLang} />}
            />
            <Route
                path="/requisites"
                element={<RequisitesPage dir={dir} changeLanguage={changeLanguage} currentLang={currentLang} />}
            />
            <Route
                path="/portfolio"
                element={<PortfolioCases dir={dir} changeLanguage={changeLanguage} currentLang={currentLang} />}
            />
            <Route path="*" element={<NotFound404 />} />
                {addressCases}
        </Routes>
    );
};

export default Main;