import React, {useEffect, useState, useRef} from 'react';
import styled from 'styled-components';
import {useTranslation} from 'react-i18next';
import Main from './Components/Main';
import AdvertisingPages from './Components/PromotionsSection/AdvertisingPages';
import Header from './Components/Header/Header';
import {WHATSAPP} from './Utils/Constants';

const AppWrapper = styled.div`
    position: relative;
    width: 100vw;
    height: 100%;
    padding: 0;
    margin: 0;
    direction: ${({$dir}) => $dir};
    display: flex;
    align-items: start;
    justify-content: center;
`;

const WhatsAppImg = styled.img`
    position: fixed;
    ${({$dir}) => ($dir === 'ltr' ? 'right' : 'left')}: 2%;
    bottom: 3%;
    width: 90px;
    height: 90px;
    z-index: 15;
    cursor: pointer;
    opacity: ${(props) => (props.$isScrolling ? '0.4' : '1')};
    transition: opacity 0.3s ease;
    
    @media (max-width: 478px) {
        width: 85px;
        height: 85px;
        bottom: 1.5%;
    }
`;

const storage = {
    get(key) {
        try { return window.localStorage.getItem(key); } catch { return null; }
    },
    set(key, value) {
        try { window.localStorage.setItem(key, value); } catch {}
    }
};

function App() {
    const { i18n } = useTranslation();
    const [direction, setDirection] = useState('ltr');
    const [currentLang, setCurrentLang] = useState(i18n.language);
    const [isScrolling, setIsScrolling] = useState(false);
    const scrollTimeoutRef = useRef(null);

    const applyDirAndHtmlAttrs = (langCode) => {
        const dir = (langCode === 'he' || langCode === 'iw') ? 'rtl' : 'ltr';
        setDirection(dir);
        document.documentElement.dir = dir;
        document.documentElement.lang = langCode;
    };

    const changeLanguage = (lang) => {
        i18n.changeLanguage(lang);
        setCurrentLang(lang);
        storage.set('app_lang', lang);
        applyDirAndHtmlAttrs(lang);
    };

    useEffect(() => {
        const saved = storage.get('app_lang');
        const initialLang = saved || i18n.language || 'en';
        if (initialLang !== i18n.language) {
            // синхронизируем i18n с сохранённым языком
            i18n.changeLanguage(initialLang);
        }
        setCurrentLang(initialLang);
        applyDirAndHtmlAttrs(initialLang);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
        const handleScroll = () => {
            setIsScrolling(true);
            if (scrollTimeoutRef.current) clearTimeout(scrollTimeoutRef.current);
            scrollTimeoutRef.current = setTimeout(() => setIsScrolling(false), 300);
        };
        window.addEventListener('scroll', handleScroll);
        return () => {
            window.removeEventListener('scroll', handleScroll);
            if (scrollTimeoutRef.current) clearTimeout(scrollTimeoutRef.current);
        };
    }, []);
    useEffect(() => {
        const handler = (lng) => applyDirAndHtmlAttrs(lng);
        i18n.on('languageChanged', handler);
        return () => i18n.off('languageChanged', handler);
    }, [i18n]);
    return (
        <AppWrapper className="row no-gutters g-0" $dir={direction}>
            <Header changeLanguage={changeLanguage} currentLang={currentLang}/>
            <AdvertisingPages dir={direction} changeLanguage={changeLanguage} currentLang={currentLang}/>
            <a
                href="https://wa.me/972547185598"
                target="_blank"
                rel="noopener noreferrer"
                aria-label="Contact via WhatsApp"
            >
                <WhatsAppImg
                    $isScrolling={isScrolling}
                    $dir={direction}
                    src={WHATSAPP}
                    alt="WhatsApp contact"
                />
            </a>
            <Main
                dir={direction}
                changeLanguage={changeLanguage}
                currentLang={currentLang}
            />
        </AppWrapper>
    );
}

export default App;
