import React, {useEffect, useState} from "react";
import styled from "styled-components";
import Burger from "./Burger";

const NavSector = styled.div`
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    width: 100vw;
    height: 12vh;
    z-index: 2000;
    background-color: #33beb3;
    display: flex;
    align-items: center;
    justify-content: center;

    @media (max-width: 978px) {
        background-color: transparent;
    }
`;

const HeadBar = styled.div`
    display: flex;
    width: 100%;
    height: 100%;
    padding: 0 3vw;
    align-items: center;
    justify-content: space-around;
    color: white;

    @media (max-width: 978px) {
        background-color: ${(props) => (props.$scrolled ? "#f8f8f8" : "inherit")};
        box-shadow: ${(props) => (props.$scrolled ? "0 4px 20px 8px rgba(53, 67, 88, 0.3);" : "none")};
        height: auto;
        padding: 1rem 0;
    }
`;

const Header = (props) => {
    const [scrolled, setScrolled] = useState(false);

    useEffect(() => {
        const handleScroll = () => {
            setScrolled(window.innerWidth < 978 && window.scrollY > 50);
        };
        window.addEventListener("scroll", handleScroll, {passive: true});
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    return (
        <NavSector id="head" $scrolled={scrolled}>
            <HeadBar $scrolled={scrolled}>
                <Burger
                    changeLanguage={props.changeLanguage}
                    currentLang={props.currentLang}
                    setRef={props.setRef}
                    burgerMenu={props.burgerMenu}
                />
            </HeadBar>
        </NavSector>
    );
};

export default Header;
