import React, { useState } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import { PORTFOLIOPIC } from "../../../Utils/Constants";
import { NavLink } from "react-router-dom";

const Section = styled.section`
  margin-top: 80px;
  padding: clamp(40px, 5vw, 80px) clamp(20px, 5vw, 80px);
  a { text-decoration: none; }
`;

const Title = styled.h2`
  font-size: clamp(26px, 3.5vw, 42px);
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 32px;
  font-weight: 600;
`;

const Grid = styled.div`
  display: grid;
  gap: 24px;
    
  grid-template-columns: 1fr;
    
  @media (min-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }
    
  @media (min-width: 1200px) {
    grid-template-columns: repeat(3, 1fr);
  }
`;

const CardLink = styled(NavLink)`
  display: block;
`;

const CaseCard = styled.div`
    background: #e8e5e1;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    text-decoration: none;
    transition: transform 0.25s ease, box-shadow 0.25s ease;
    cursor: pointer;
    box-shadow: 20px 20px 20px gray;

    &:hover {
        transform: translateY(-4px);
        box-shadow: 0 14px 40px rgba(0, 0, 0, 0.3);
    }

    img {
        width: 100%;
        height: auto;
        display: block;
    }
`;

const CaseInfo = styled.div`
    padding: 18px 20px 24px;
`;

const CaseTitle = styled.h3`
    font-size: clamp(16px, 1.6vw, 20px);
    margin: 0 0 4px;
    color: #354358;
    font-weight: 500;
    letter-spacing: 1px;
`;

const SectionSubTitle = styled.span`
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: end;
`;

const CaseSubtitle = styled.p`
    margin: 1vh 0 0 0;
    font-size: 1.7vh;
    color: white;
    width: fit-content;
    border-radius: 25px;
    padding: 3px 15px;
    background-color: #354358;
`;

const ButtonWrapper = styled.div`
    display: flex;
    justify-content: center;
    margin-top: 40px;
`;

const MoreButton = styled.button`
    background: transparent;
    border: 2px solid #fff;
    color: #fff;
    font-size: 15px;
    letter-spacing: 0.5px;
    border-radius: 50px;
    padding: 10px 26px;
    cursor: pointer;
    transition: all 0.25s ease;
    text-transform: uppercase;

    &:hover {
        background: #fff;
        color: #1b1a1a;
    }
`;

export default function PortfolioCases() {
    const [showAll, setShowAll] = useState(false);
    const { t, i18n } = useTranslation();

    const dir =
        typeof i18n.dir === "function" ? i18n.dir() : (i18n.language === "he" ? "rtl" : "ltr");

    const casesText = t("cases_description", { returnObjects: true }) || [];
    const visibleCases = showAll ? PORTFOLIOPIC : PORTFOLIOPIC.slice(0, 3);

    return (
        <Section dir={dir}>
            <Title>{t("cases_description_title")}</Title>

            <Grid>
                {visibleCases.map((c) => {
                    const caseText = casesText.find((item) => item.slug === c.slug);
                    const title = caseText?.caseTitle || c.alt || "Проект";
                    const tariff = caseText?.caseTariff || " ";
                    const to = `/${c.slug}`;

                    return (
                        <CardLink to={to} aria-label={title} key={c.slug || c.src}>
                            <CaseCard>
                                <img src={c.src} alt={c.alt || title} loading="lazy" />
                                <CaseInfo>
                                    <CaseTitle>{title}</CaseTitle>
                                    <SectionSubTitle>
                                        <CaseSubtitle>{tariff}</CaseSubtitle>
                                    </SectionSubTitle>
                                </CaseInfo>
                            </CaseCard>
                        </CardLink>
                    );
                })}
            </Grid>

            {!showAll && PORTFOLIOPIC.length > 3 && (
                <ButtonWrapper>
                    <MoreButton onClick={() => setShowAll(true)}>
                        {t("cases_description_button")}
                    </MoreButton>
                </ButtonWrapper>
            )}
        </Section>
    );
}
