import React, {useEffect, useRef, useState} from "react";
import styled from "styled-components";

import picBackgroundHe from "../../Images/w22_he_desctop.webp";
import picBackgroundHe2 from "../../Images/w33_he_desck.webp";
import picBackgroundHe3 from "../../Images/w2_he_desk.webp";

import picBackground from "../../Images/w22_desctop.webp";
import picBackground2 from "../../Images/w33_desck.webp";
import picBackground3 from "../../Images/w2_desk.webp";

import picBackgroundMobile from "../../Images/w22_mobile.webp";
import picBackground2Mobile from "../../Images/w33_mobile.webp";
import picBackground3Mobile from "../../Images/w2_mobile.webp";

import {HONEYCOMB, HONEYCOMB_1, LOGO_BLUE} from "../../Utils/Constants";
import {useTranslation} from "react-i18next";
import About from "../About/About";
import Contact from "../Contact/Contact";
import Footer from "../Footer/Footer";
import ContactsPage from "../Contact/ContactsPage";
import ShotSurveyModal from "../../Utils/ShotSurveyModal";


const HEADER_HEIGHT = 70;
const HERO_BACKFILL = "#f8f8f8";

const HomeAll = styled.div`
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-around;
    width: 100%;
    height: 100%;
    hyphens: manual;

    a {
        text-decoration: none;
    }

    @media (max-width: 1030px) {
        align-items: flex-start;
        justify-content: flex-start;
    }
`;

const HomeWrapper = styled.div`
    background-color: ${HERO_BACKFILL};
    min-height: calc(100dvh - ${HEADER_HEIGHT}px);
    padding-top: ${HEADER_HEIGHT}px;
    display: flex;
    align-items: center;
    justify-content: start;
    position: relative;
    box-sizing: border-box;
    width: 100%;

    @supports not (height: 1dvh) {
        min-height: calc(100svh - ${HEADER_HEIGHT}px);
    }
    @supports not (height: 1svh) {
        min-height: calc(100vh - ${HEADER_HEIGHT}px);
    }
    @media (max-width: 1030px) {
        flex-direction: column;
        align-items: center;
        justify-content: center;
    }
`;

const HeroImg = styled.img`
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: top center;
    z-index: 0;
    pointer-events: none;
    opacity: ${p => (p.$visible ? 1 : 0)};
    transition: opacity .25s linear;
    background-color: ${HERO_BACKFILL};
`;

const Content = styled.div`
    margin-inline-start: 3vw;
    margin-top: 4vw;
    display: flex;
    flex-direction: column;
    width: 45vw;
    justify-content: center;
    align-items: center;
    letter-spacing: 3px;
    font-weight: bold;
    position: relative;
    direction: ${p => (p.$dir === "rtl" ? "rtl" : "ltr")};
    color: #354358;
    gap: 16px;
    height: auto;
    min-height: max-content;

    @media (max-width: 1030px) {
        width: 90vw;
        margin-inline-start: 0;
        margin-top: clamp(50dvh, 75dvh, 60dvh);
    }

    @media (max-width: 478px) {
        width: 97vw;
        padding: 0 12px;
        gap: 12px;
        margin-top: 33dvh;
    }
`;

const Slogan = styled.h1`
    font-size: 5vh;
    margin: 0;
    font-weight: bold;
    text-transform: uppercase;
    text-align: center;
    color: #354358;

    @media (max-width: 1500px) {
        font-size: 3vh;
        line-height: 4vh;
    }

    @media (max-width: 1030px) {
        order: 1;
        font-size: 2.5vh;
        margin-top: 2vh;
        margin-bottom: 0;
    }
`;
const SubSlogan = styled.p`
    text-align: center;
    font-size: 3vh;
    letter-spacing: 2px;
    padding: 0 1vw;
    max-width: 70%;

    @media (max-width: 1500px) {
        font-size: 2vh;
        line-height: 3vh;
    }

    @media (max-width: 1030px) {
        order: 1;
        font-size: 2.5vh;
        max-width: 90%;
    }
    @media (max-width: 478px) {
        font-size: 2.3vh;
        max-width: 90%;
        margin: 1vh;
        line-height: normal;
        font-weight: 600;
    }
`;
const LogoName2 = styled.img`
    width: 25vh;
    margin-bottom: 1vw;
    animation: ${p => p.$dir === "rtl" ? "slideLeftLogo 2.5s forwards" : "slideRightLogo 2.5s forwards"};

    @keyframes slideRightLogo {
        0% {
            transform: translateX(-200%);
        }
        100% {
            transform: translateX(0%);
        }
    }
    @keyframes slideLeftLogo {
        0% {
            transform: translateX(400%);
        }
        100% {
            transform: translateX(0%);
        }
    }

    @media (max-width: 1030px) {
        display: none;
        margin-bottom: 2vh;
    }
`;

const Line = styled.div` height: .3vh;
    width: 100%;
    margin: 0; `;

const Circle = styled.img`
    position: absolute;
    ${p => (p.$dir === "rtl" ? "right" : "left")}: 5%;
    top: 300vh;
    opacity: .15;
    width: 60vh;
    height: auto;
    @media (max-width: 1030px) {
        display: none;
    }
`;

const imgSrc = (img) => (typeof img === "string" ? img : img?.src || "");

const useIsMobile = () => {
    const [isMobile, setIsMobile] = useState(false);
    useEffect(() => {
        const mq = window.matchMedia("(max-width: 1030px), (orientation: portrait)");
        const onChange = () => setIsMobile(mq.matches);
        onChange();
        mq.addEventListener ? mq.addEventListener("change", onChange) : mq.addListener(onChange);
        return () => {
            mq.removeEventListener ? mq.removeEventListener("change", onChange) : mq.removeListener(onChange);
        };
    }, []);
    return isMobile;
};

const ButtonArea = styled.div`
    position: relative;
    width: calc(23vh + (20vh * 2));
    height: fit-content;
    display: grid;
    place-items: center;
    z-index: 5;
    overflow: visible;
`;

const MainButton = styled.button`
    position: relative;
    width: 23vh;
    height: 23vh;
    border-radius: 50%;
    border: 0;
    background: #33beb3;
    color: #fff;
    text-wrap: nowrap;
    font-weight: 800;
    letter-spacing: .12em;
    text-transform: uppercase;
    font-size: 2.1vh;
    display: grid;
    place-items: center;
    cursor: pointer;
    transition: transform .25s ease, background .2s ease, box-shadow .2s ease;
    outline: none;
    opacity: 0;
    animation: slideUpButton 0.9s ease-out forwards;
    @keyframes slideUpButton {
        from {
            transform: translateY(150%);
            opacity: 0;
        }
        to {
            transform: translateY(0);
            opacity: 1;
        }
    }
    transform: ${({$open}) => ($open ? 'translateZ(0) scale(1.03)' : 'translateZ(0) scale(1)')};

    &:hover, &:focus-visible, &:active {
        background: #596573;
    }

    @media (max-width: 1030px) {
        font-size: 1.8vh;
    }
    @media (max-width: 678px) {
        font-size: 2vh;
    }
`;

const Bubble = styled.a`
    position: absolute;
    left: 50%;
    top: 50%;
    width: 12vh;
    height: 12vh;
    border-radius: 50%;
    display: grid;
    place-items: center;
    font-weight: 900;
    color: #fff;
    text-decoration: none;
    user-select: none;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
    opacity: ${({$open}) => ($open ? 1 : 0)};
    pointer-events: ${({$open}) => ($open ? 'auto' : 'none')};
    transform: translate(-50%, -50%) rotate(${({$open, $angle = 270}) =>
            ($open ? $angle : $angle - 20)}deg) translate(${({$radius}) => $radius || 'var(--orbitR)'}) 
            rotate(${({$open, $angle = 27}) => ($open ? -$angle : -($angle - 20))}deg);
    transition: transform .60s cubic-bezier(.2, .8, .2, 1), opacity .35s ease;
    transition-delay: ${({$delay = 0}) => `${$delay}ms`};

    &[data-color="lite"] {
        background: #33beb3;
    }

    &[data-color="mid"] {
        background: #354358;
    }

    &[data-color="pro"] {
        background: #ff7a59;
    }

    font-size: 2vh;

    &::after {
        content: attr(data-label);
        position: absolute;
        opacity: 0;
        transform: scale(.96);
        transition: opacity .18s ease, transform .18s ease;
        inset: 0;
        display: grid;
        place-items: center;
    }

    &:hover {
        color: transparent !important;
    }

    &:hover::after {
        opacity: 1;
        color: white !important;
    }

    @media (max-width: 1030px) {
        width: 10vh;
        height: 10vh;
        font-size: 1.7vh;
        transform: translate(-50%, -50%) rotate(${({$open, $angle = 70
        }) => ($open ? $angle : $angle - 50)}deg) translate(17vh)
        rotate(${({$open, $angle = 70}) => ($open ? -$angle : -($angle - 50))}deg);
    }
`;

const Home = (props) => {
    const {t, i18n} = useTranslation();
    const [direction, setDirection] = useState("ltr");
    const [open, setOpen] = useState(false);
    const isMobile = useIsMobile();
    const wantLabel = t("ui.want");

    const [stage, setStage] = useState(1);
    const heroRef = useRef(null);

    const [surveyOpen, setSurveyOpen] = useState(false);
    const [surveyPlan, setSurveyPlan] = useState(null);

    // флаг: подавить «следующий click» после тача (чтобы не было двойного срабатывания)
    const suppressClickRef = useRef(false);

    const openSurvey = (plan) => {
        setSurveyPlan(plan);
        setSurveyOpen(true);
        setOpen(false); // закрываем пузырьки после выбора
    };

    const CLOSE_AT = 20;
    const SMILE_AT = 80;

    useEffect(() => {
        setDirection(i18n.language === "he" ? "rtl" : "ltr");
    }, [i18n.language]);

    useEffect(() => {
        [picBackgroundHe, picBackgroundHe2, picBackgroundHe3, picBackground, picBackground2, picBackground3,
            picBackgroundMobile, picBackground2Mobile, picBackground3Mobile].forEach((img) => {
            const i = new Image();
            i.src = imgSrc(img);
        });
    }, []);

    useEffect(() => {
        let rafId = 0;
        const update = () => {
            const wrap = heroRef.current;
            const y = window.scrollY || document.documentElement.scrollTop || 0;
            if (wrap) {
                const start = wrap.offsetTop;
                const rel = Math.max(0, y - start);
                let next = 1;
                if (rel > CLOSE_AT) next = 0;
                if (rel > SMILE_AT) next = 2;
                setStage((prev) => (prev === next ? prev : next));
            }
            rafId = 0;
        };
        const onScroll = () => {
            if (!rafId) rafId = requestAnimationFrame(update);
        };
        window.addEventListener("scroll", onScroll, {passive: true});
        window.addEventListener("resize", onScroll, {passive: true});
        onScroll();
        return () => {
            window.removeEventListener("scroll", onScroll);
            window.removeEventListener("resize", onScroll);
            if (rafId) cancelAnimationFrame(rafId);
        };
    }, []);

    const isRTL = direction === "rtl";

    const srcClosed = imgSrc(isMobile ? picBackgroundMobile : (isRTL ? picBackgroundHe : picBackground));
    const srcOpen = imgSrc(isMobile ? picBackground2Mobile : (isRTL ? picBackgroundHe2 : picBackground2));
    const srcSmile = imgSrc(isMobile ? picBackground3Mobile : (isRTL ? picBackgroundHe3 : picBackground3));

    const sizes = isMobile ? "100vw" : "(max-width: 1030px) 100vw, 100vw";
    const srcSetOpen = `${srcOpen} 1x`;
    const srcSetClosed = `${srcClosed} 1x`;
    const srcSetSmile = `${srcSmile} 1x`;

    const handleAreaPointerEnter = (e) => {
        if (e.pointerType === "mouse") setOpen(true);
    };
    const handleAreaPointerLeave = (e) => {
        if (e.pointerType === "mouse") setOpen(false);
    };

    const handleMainPointerDown = (e) => {
        if (e.pointerType !== "mouse") {
            e.preventDefault();
            suppressClickRef.current = true;
            setOpen((v) => !v);
        }
    };
    const handleMainClick = (e) => {
        if (suppressClickRef.current) {
            e.preventDefault();
            suppressClickRef.current = false;
            return;
        }
        setOpen((v) => !v);
    };

    const onBubbleTouch = (plan) => (e) => {
        if (e.nativeEvent && e.nativeEvent.pointerType && e.nativeEvent.pointerType !== "mouse") {
            e.preventDefault();
            e.stopPropagation();
        } else {
            e.preventDefault();
        }
        openSurvey(plan);
    };

    return (
        <HomeAll id="home">
            <HomeWrapper ref={heroRef}>
                <HeroImg src={srcOpen} srcSet={srcSetOpen} sizes={sizes} width={1920} height={1080} alt=""
                         decoding="async" $visible={stage === 1}/>
                <HeroImg src={srcClosed} srcSet={srcSetClosed} sizes={sizes} width={1920} height={1080} alt=""
                         decoding="async" $visible={stage === 0}/>
                <HeroImg src={srcSmile} srcSet={srcSetSmile} sizes={sizes} width={1920} height={1080} alt=""
                         decoding="async" $visible={stage === 2}/>

                <ShotSurveyModal
                    open={surveyOpen}
                    plan={surveyPlan}
                    dir={direction}
                    onClose={() => setSurveyOpen(false)}
                    onSubmit={(payload) => {
                        console.log("shot survey:", payload);
                    }}
                />

                <Content $dir={direction}>
                    <LogoName2 src={LOGO_BLUE} alt="logo" $dir={direction}/>
                    <Slogan>{t("home.slogan")}</Slogan>
                    <SubSlogan>{t("home.sub_slogan")}</SubSlogan>

                    <ButtonArea
                        onPointerEnter={handleAreaPointerEnter}
                        onPointerLeave={handleAreaPointerLeave}
                    >
                        <MainButton
                            type="button"
                            aria-haspopup="true"
                            aria-expanded={open}
                            $open={open}
                            onPointerDown={handleMainPointerDown}
                            onClick={handleMainClick}
                        >
                            {t("home.order_button")}
                        </MainButton>

                        <Bubble
                            href="#pricing-lite"
                            data-color="lite"
                            data-label={wantLabel}
                            $open={open}
                            $angle={200}
                            $radius="20vh"
                            $delay={0}
                            onClick={onBubbleTouch("Standard")}
                        >
                            1900 ILS
                        </Bubble>

                        <Bubble
                            href="#pricing-mid"
                            id="pricing-mid"
                            data-color="mid"
                            data-label={wantLabel}
                            $open={open}
                            $angle={350}
                            $radius="22vh"
                            $delay={70}
                            onClick={onBubbleTouch("Pro")}
                        >
                            3500 ILS
                        </Bubble>

                        <Bubble
                            href="#pricing-pro"
                            data-color="pro"
                            data-label={wantLabel}
                            $open={open}
                            $angle={400}
                            $radius="20vh"
                            $delay={140}
                            onClick={onBubbleTouch("Business")}
                        >
                            8200 ILS
                        </Bubble>
                    </ButtonArea>
                </Content>
            </HomeWrapper>

            <Line/>
            {direction === "rtl"
                ? <Circle $dir={direction} src={HONEYCOMB} alt="circle"/>
                : <Circle $dir={direction} src={HONEYCOMB_1} alt="circle"/>}

            <About/>
            <Contact/>
            <ContactsPage currentLang={props.currentLang} direction={direction}/>
            <Footer/>
        </HomeAll>
    );
};

export default Home;
