const GlobalStyle = createGlobalStyle`

    :root {
        background-color: #f8f8f8;
    }

    html {
        display: flex;
        align-items: flex-start;
        justify-content: center;
        margin: 0;
        padding: 0;
        width: 100vw;
        box-sizing: border-box;
        flex-wrap: wrap;
        overflow-x: hidden;
        background-color: #f8f8f8;
        -webkit-text-size-adjust: 100%;
        text-size-adjust: 100%;
        -webkit-font-smoothing: antialiased;
        text-rendering: optimizeLegibility;
        font-family: Oswald, "Noto Serif Hebrew", sans-serif;
    }

    a {
        font-family: Oswald, "Noto Serif Hebrew", sans-serif;
    }

    body {
        margin: 0;
        padding: 0;
        width: 100vw;
        background-color: #f8f8f8;
        letter-spacing: 0.02em;
        text-align: center;
        overflow-x: hidden;
        font-family: Oswald, "Noto Serif Hebrew", -apple-system, BlinkMacSystemFont, sans-serif;
        -webkit-font-smoothing: antialiased;
        -moz-osx-font-smoothing: grayscale;
        text-rendering: optimizeLegibility;
    }

    .lazy-section {
        content-visibility: auto;
        contain-intrinsic-size: 1200px 900px;
    }

    *,
    *:before,
    *:after {
        box-sizing: inherit;
    }

    h1, h2, h3 {
        letter-spacing: 0.01em;
        margin: 0;
        line-height: 1.2;
        text-align: center;
        font-family: Oswald, "Noto Serif Hebrew", sans-serif;

        @media (max-width: 478px) {
            line-height: 1.15;
        }
    }

    h1 {
        color: #354358;
        font-weight: bold;
        text-transform: uppercase;
    }

    h2 {
        color: #009688;
        font-weight: normal;
    }

    p {
        font-size: 2.5vh;
        font-family: Oswald, "Noto Serif Hebrew", sans-serif;
    }

    .swiper-button-prev,
    .swiper-button-next {
        width: 40px;
        height: 40px;
        background: rgba(0, 150, 136, 0.7);
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        color: white !important;
        font-size: 16px;
        -webkit-tap-highlight-color: transparent;
    }

    .swiper-button-prev::after,
    .swiper-button-next::after {
        content: '←' !important;
        font-size: 25px;
        font-weight: bold;
    }

    .swiper-button-next::after {
        content: '→' !important;
    }

    @media (prefers-reduced-motion: reduce) {
        .swiper-slide {
            transition: none !important;
        }
        .swiper-button-prev::after {
            content: '←';
        }
        .swiper-button-next::after {
            content: '→';
        }
    }
`;

const rootElement = document.getElementById('root');
const root = createRoot(rootElement);

root.render(
    <React.StrictMode>
        <GlobalStyle />
        <BrowserRouter>
            <App />
        </BrowserRouter>
    </React.StrictMode>
);

reportWebVitals();