import React, {useRef} from "react";
import styled from "styled-components";
import {useTranslation} from "react-i18next";
import * as emailjs from "@emailjs/browser";

const Backdrop = styled.div`
    position: fixed;
    inset: 0;
    z-index: 9000;
    display: grid;
    place-items: center;
    padding: 16px;
    background: white;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    height: 100vh;

    @media (max-width: 480px) {
        padding: 8px;
        margin: auto;
        width: 90vw;
    }
`;

const Card = styled.div`
    margin-top: 8%;
    width: min(70vw, 720px);
    max-height: 70dvh;
    background: #f8f8f8;
    padding: 18px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
    display: flex;
    flex-direction: column;
    gap: 12px;

    @supports not (height: 1dvh) {
        max-height: 92vh;
    }

    @media (max-width: 900px) {
        width: min(96vw, 640px);
        padding: 16px;
        border-radius: 16px;
    }

    @media (max-width: 600px) {
        width: 100%;
        padding: 12px;
        border-radius: 12px;
    }
`;

const Header = styled.div`
    position: relative;
    display: grid;
    gap: 8px;
    flex: 0 0 auto;

    a { word-break: break-word; }
`;

const CloseBtn = styled.button`
    position: absolute;
    top: 0;
    ${({$dir}) => ($dir === 'ltr' ? 'right: 0;' : 'left: 0;')};
    border: 0;
    border-radius: 10px;
    padding: 8px 12px;
    font-weight: 800;
    cursor: pointer;
    color: white;
    letter-spacing: 2px;
    background: #354358;

    &:hover { background: #33beb3; }

    @media (max-width: 600px) {
        padding: 7px 10px;
        font-size: 14px;
    }
`;

const Title = styled.h3`
    margin: 2vh 0;
    font-size: 22px;
    font-weight: 900;
    color: #1d3557;
    letter-spacing: 1px;
`;

const Sub = styled.p`
    margin: 1vh 0;
    color: #354358;

    a {
        text-decoration: none;
        color: #009688;
        letter-spacing: 1px;
        font-size: 2.5vh;
    }
`;

const Badge = styled.span`
    display: flex;
    align-items: center;
    justify-content: center;
    width: fit-content;
    height: fit-content;
    padding: 5px 20px;
    border-radius: 25px;
    background: #33beb3;
    color: #fff;
    font-weight: 800;
    font-size: 2vh;
    letter-spacing: 2px;
`;

const FormEl = styled.form`
    display: grid;
    gap: 12px;
    flex: 1 1 auto;
    overflow: auto;
    padding-right: 4px;
    scrollbar-width: thin;

    &::-webkit-scrollbar { width: 8px; }
    &::-webkit-scrollbar-thumb { background: #d7e6e9; border-radius: 8px; }
`;

const Row = styled.div`
    display: grid;
    gap: 8px;
`;

const Two = styled.div`
    display: grid;
    gap: 12px;
    grid-template-columns: 1fr 1fr;

    @media (max-width: 900px) {
        grid-template-columns: 1fr;
    }
`;

const Label = styled.label`
    font-size: 14px;
    font-weight: 700;
    color: #354358;

    @media (max-width: 600px) {
        font-size: 13px;
    }
`;
const InputInv = styled.input`
    visibility: hidden;
`;

const Input = styled.input`
    width: 100%;
    padding: 10px 12px;
    border-radius: 12px;
    border: 1px solid #dbe5ea;
    outline: none;
    font-size: 14px;
    line-height: 1.4;

    &::placeholder{
        color: #6f8290;
        letter-spacing: .06em;
        font-size: 15px;
        opacity: .95;
    }

    &:focus {
        border-color: #33beb3;
        box-shadow: 0 0 0 3px rgba(51,190,179,.15);
        font-size: 14px;
    }

    @media (max-width: 600px) {
        padding: 9px 11px;
        border-radius: 10px;
        font-size: 13.5px;

        &::placeholder{ font-size: 14px; }
    }
`;

const Textarea = styled.textarea`
    width: 100%;
    min-height: 90px;
    padding: 10px 12px;
    border-radius: 12px;
    border: 1px solid #dbe5ea;
    outline: none;
    resize: vertical;
    font-size: 14px;
    line-height: 1.5;

    &::placeholder{
        color: #6f8290;
        letter-spacing: .06em;
        font-size: 15px;
        opacity: .95;
    }

    &:focus {
        border-color: #33beb3;
        box-shadow: 0 0 0 3px rgba(51,190,179,.15);
        font-size: 14px;
    }

    @media (max-width: 600px) {
        min-height: 80px;
        padding: 9px 11px;
        border-radius: 10px;
        font-size: 13.5px;

        &::placeholder{ font-size: 14px; }
    }
`;

const Select = styled.select`
    width: 100%;
    padding: 10px 12px;
    border-radius: 12px;
    border: 1px solid #dbe5ea;
    outline: none;
    background: #fff;
    font-size: 14px;
    letter-spacing: .04em;

    &:focus {
        border-color: #33beb3;
        box-shadow: 0 0 0 3px rgba(51,190,179,.15);
    }

    @media (max-width: 600px) {
        padding: 9px 11px;
        border-radius: 10px;
        font-size: 13.5px;
    }
`;

const Actions = styled.div`
    display: flex;
    gap: 12px;
    justify-content: flex-end;
    margin-top: 4px;
    flex: 0 0 auto;

    @media (max-width: 600px) {
        gap: 8px;
    }
`;

const Btn = styled.button`
    border: 0;
    border-radius: 12px;
    padding: 10px 14px;
    cursor: pointer;
    font-weight: 800;
    color: #fff;
    background: #009688;
    letter-spacing: 2px;
    &:hover { background: #33beb3; }

    @media (max-width: 600px) {
        padding: 9px 12px;
        border-radius: 10px;
        font-size: 14px;
    }
`;

function ShotSurveyModal({open, plan, onClose, onSubmit, dir}) {
    const {t} = useTranslation();
    const form = useRef();

    if (!open || !plan) return null;

    const price = t(`shot_survey.plans.${plan}.price`);
    const href = t(`shot_survey.plans.${plan}.href`);
    const title = t(`shot_survey.modal.title.${plan}`);
    const linkText = t(`shot_survey.modal.linkText.${plan}`);

    const handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) onClose();
    };

    const sendEmail = (e) => {
        e.preventDefault();
        emailjs
            .sendForm('service_2x2mzyk', 'template_hz6i2u7', form.current, {
                publicKey: 'J49jxAIokBf4t0-1_',
            })
            .then(
                () => {
                    e.target.reset();
                },
                (error) => {
                    console.log('FAILED...', error.text);
                },
            );
        onClose();
    };

   /* const submit = (e) => {
        e.preventDefault();
        const data = new FormData(e.currentTarget);
        const payload = Object.fromEntries(data.entries());
        payload.plan = plan;
        if (onSubmit) onSubmit(payload);
        onClose();
    };*/

    return (
        <Backdrop onClick={handleBackdropClick} role="dialog" aria-modal="true">
            <Card onClick={(e) => e.stopPropagation()}>
                <Header>
                    <Badge>{t("shot_survey.modal.badge", {price})}</Badge>
                    <Title>{title}</Title>
                    {/*<Sub>*/}
                    {/*    <a href={href} target="_blank" rel="noopener noreferrer">{linkText}</a>*/}
                    {/*</Sub>*/}
                    <CloseBtn  type="button" onClick={onClose} $dir={dir}>{t("shot_survey.form.cancel")}</CloseBtn>
                </Header>

                <FormEl ref={form} onSubmit={sendEmail}>
                    <Two>
                        <Row>
                            <Label htmlFor="name">{t("shot_survey.form.name")}</Label>
                            <Input id="name" name="name" required placeholder={t("shot_survey.form.name")} />
                        </Row>
                        <Row>
                            <Label htmlFor="company">{t("shot_survey.form.company")}</Label>
                            <Input id="company" name="company" placeholder={t("shot_survey.form.company")} />
                        </Row>
                    </Two>

                    <Two>
                        <Row>
                            <Label htmlFor="phone">{t("shot_survey.form.phone")}</Label>
                            <Input id="phone" name="phone" placeholder="+972 5X XXX XXXX" />
                        </Row>
                        <Row>
                            <Label htmlFor="email">{t("shot_survey.form.email")}</Label>
                            <Input id="email" type="email" name="email" placeholder="you@example.com" />
                        </Row>
                    </Two>

                    <Row>
                        <Label htmlFor="business">{t("shot_survey.form.business")}</Label>
                        <Input id="business" name="business" placeholder={t("shot_survey.form.business_ph")} />
                    </Row>

                    <Row>
                        <Label htmlFor="location">{t("shot_survey.form.location")}</Label>
                        <Input id="location" name="location" placeholder={t("shot_survey.form.location_ph")} />
                    </Row>

                    <Row>
                        <Label htmlFor="links">{t("shot_survey.form.links")}</Label>
                        <Textarea id="links" name="links" placeholder="https://..., @instagram, ..." />
                    </Row>

                    <Two>
                        <Row>
                            <Label htmlFor="brandStyle">{t("shot_survey.form.brandStyle")}</Label>
                            <Select id="brandStyle" name="brandStyle" defaultValue="">
                                <option value="" disabled style={{color:'#8a98a6'}}>{t("shot_survey.form.brandStyle_opt.choose")}</option>
                                <option value="yes">{t("shot_survey.form.brandStyle_opt.yes")}</option>
                                <option value="no">{t("shot_survey.form.brandStyle_opt.no")}</option>
                                <option value="specify">{t("shot_survey.form.brandStyle_opt.specify")}</option>
                            </Select>
                        </Row>
                        <Row>
                            <Label htmlFor="hasSite">{t("shot_survey.form.hasSite")}</Label>
                            <Select id="hasSite" name="hasSite" defaultValue="">
                                <option value="" disabled style={{color:'#8a98a6'}}>{t("shot_survey.form.hasSite_opt.choose")}</option>
                                <option value="no">{t("shot_survey.form.hasSite_opt.no")}</option>
                                <option value="update">{t("shot_survey.form.hasSite_opt.update")}</option>
                                <option value="new">{t("shot_survey.form.hasSite_opt.new")}</option>
                            </Select>
                        </Row>
                    </Two>

                    <Row>
                        <Label htmlFor="deadline">{t("shot_survey.form.deadline")}</Label>
                        <Select id="deadline" name="deadline" defaultValue="">
                            <option value="" disabled style={{color:'#8a98a6'}}>{t("shot_survey.form.deadline_opt.choose")}</option>
                            <option value="urgent">{t("shot_survey.form.deadline_opt.urgent")}</option>
                            <option value="month">{t("shot_survey.form.deadline_opt.month")}</option>
                            <option value="noRush">{t("shot_survey.form.deadline_opt.noRush")}</option>
                        </Select>
                    </Row>

                    <Row>
                        <Label htmlFor="goal">{t("shot_survey.form.goal")}</Label>
                        <Select id="goal" name="goal" defaultValue="">
                            <option value="" disabled style={{color:'#8a98a6'}}>{t("shot_survey.form.goal_opt.choose")}</option>
                            <option value="leads">{t("shot_survey.form.goal_opt.leads")}</option>
                            <option value="brand">{t("shot_survey.form.goal_opt.brand")}</option>
                            <option value="sales">{t("shot_survey.form.goal_opt.sales")}</option>
                            <option value="other">{t("shot_survey.form.goal_opt.other")}</option>
                        </Select>
                    </Row>
                    <InputInv name="plan" value={plan} />

                    <Actions>
                        <Btn type="submit">{t("shot_survey.form.submit")}</Btn>
                    </Actions>
                </FormEl>
            </Card>
        </Backdrop>
    );
}

export default ShotSurveyModal;
