import React, {useEffect, useRef, useState} from "react";
import styled from "styled-components";
import {LOGO_BLUE, LOGO_WHITE} from "../../Utils/Constants";
import {faChevronDown, faGlobe} from "@fortawesome/free-solid-svg-icons";
import {FontAwesomeIcon} from "@fortawesome/react-fontawesome";
import {useTranslation} from "react-i18next";

const RightNavWrapper = styled.div`
    width: 100vw;
    height: 12vh;
    padding: 0 3vw;
    display: flex;
    align-items: center;
    justify-content: center;
`;

const UL = styled.ul`
    list-style: none;
    height: 12vh;
    margin: 0;
    padding: 0;
    display: flex;
    width: 100vw;
    align-items: center;
    justify-content: space-between;
    letter-spacing: 2px;
    font-weight: bold;
    font-size: 1.8vw;
    flex-flow: row nowrap;

    @media (max-width: 978px) {
        position: fixed;
        flex-direction: column;
        justify-content: start;
        background-color: #f8f8f8;
        top: 0;
        right: 0;
        height: 100vh;
        width: 100vw;
        padding: 5vh 2vw;
        display: ${({$open}) => ($open ? "flex" : "none")};
        overflow-y: auto;
    }
`;

const LogoLink = styled.a`
    text-decoration: none;
`;

const LogoSection = styled.div`
    width: 100%;
    height: auto;
    display: flex;
    align-items: center;
    justify-content: flex-start;
`;

const LogoMobile = styled.img`
    padding: 2vw 0;
    width: 35vw;
    height: auto;
    @media (max-width: 978px) {
        width: 15vw;
    }
    @media (max-width: 478px) {
        width: 25vw;
    }
`;

const Logo = styled.img`
    width: 8vw;
    @media (max-width: 478px) {
        margin-bottom: 3vh;
    }
`;

const NabBar = styled.nav`
    display: flex;
    align-items: center;
    gap: 2vw;

    a {
        color: ${({$scrolled}) => ($scrolled ? "#354358" : "white")};
        text-decoration: none;
        font-size: 1.6vw;
        transition: transform 0.3s ease, color 0.3s ease;

        &:hover {
            transform: scale(1.2);
        }

        &:active {
            color: #33beb3;
        }

        @media (max-width: 978px) {
            font-size: 3.5vh;
            color: #354358;
        }
    }

    @media (max-width: 978px) {
        flex-direction: column;
        align-items: center;
        justify-content: start;
        gap: 1.5vh;
        margin-top: 3vh;
    }
`;

const Tel = styled.div`
    direction: ltr;
    color: ${({$scrolled}) => ($scrolled ? "#354358" : "white")};
    font-weight: bold;
    font-size: 1.6vw;
    transition: color 0.3s ease;

    @media (max-width: 978px) {
        font-size: 3.5vh;
        color: #33beb3;
        margin: 2vh 0;
    }
`;

const Dropdown = styled.div`
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    margin-inline-end: 2vw;

    svg {
        margin: 0 0.5vw;
    }

    button {
        background: none;
        border: none;
        cursor: pointer;
        color: ${({$scrolled}) => ($scrolled ? "#354358" : "white")};
        display: flex;
        align-items: center;
        width: 100%;
        transition: color 0.3s ease;

        p {
            font-size: 1.6vw;
            margin: 0 0.3vw;
            font-weight: bolder;
            letter-spacing: 2px;
        }

        @media (max-width: 978px) {
            color: #33beb3;
            font-size: 3.5vh;
            margin-top: 6vh;
            font-weight: bolder;

            p {
                font-size: 3.5vh;
            }
        }

        @media (max-width: 978px) {
            svg {
                margin: 0 2vw;
            }
        }
    }

    div {
        position: absolute;
        top: 100%;
        left: auto;
        width: 100%;
        background: #f8f8f8;
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
        display: ${({$show}) => ($show ? "flex" : "none")};
        flex-direction: column;
        padding: 1vh;

        p {
            cursor: pointer;
            font-size: 1.4vw;
            color: #354358;
            margin: 0;
            padding: 5px 20px;
            letter-spacing: 2px;

            &:hover {
                color: #33beb3;
            }

            @media (max-width: 978px) {
                font-size: 3.5vh;
            }
        }

        @media (max-width: 978px) {
            width: fit-content;
        }
    }
`;

const RightNav = (props) => {
    const {t, i18n} = useTranslation();
    const [isShowDropDown, setShowDropDown] = useState(false);
    const [address, setAddress] = useState("/survey-form-eng");
    const [isMobile, setIsMobile] = useState(false);
    const dropdownRef = useRef(null);

    useEffect(() => {
        const check = () => setIsMobile(window.innerWidth < 978);
        check();
        window.addEventListener("resize", check, {passive: true});
        return () => window.removeEventListener("resize", check);
    }, []);

    useEffect(() => {
        const lang = props.currentLang;
        setAddress(lang === "ru" ? "/survey-form-ru" : lang === "he" || lang === "iw" ? "/survey-form-he" : "/survey-form-eng");
    }, [props.currentLang]);

    const handleClickSurvey = () => {
    };

    const changeLanguage = (lng) => {
        i18n.changeLanguage(lng);
        props.changeLanguage(lng);
        setShowDropDown(false);
        props.setOpen(false);
    };

    useEffect(() => {
        const onDocClick = (e) => {
            if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
                setShowDropDown(false);
            }
        };
        const onEsc = (e) => {
            if (e.key === "Escape") setShowDropDown(false);
        };
        document.addEventListener("mousedown", onDocClick);
        document.addEventListener("keydown", onEsc);
        return () => {
            document.removeEventListener("mousedown", onDocClick);
            document.removeEventListener("keydown", onEsc);
        };
    }, []);

    const scrolled = !!props.scrolled; // прокидывай из Header

    return (<RightNavWrapper>
            {isMobile ? (<LogoSection>
                    <a href="/" onClick={() => props.setOpen(false)}>
                        <LogoMobile src={LOGO_BLUE} alt="logo"/>
                    </a>
                </LogoSection>) : null}

            <UL $open={props.open}>
                <LogoLink href="/" onClick={() => props.setOpen(false)}>
                    <Logo src={scrolled || isMobile ? LOGO_BLUE : LOGO_WHITE} alt="logo"/>
                </LogoLink>

                <Tel $scrolled={scrolled}>+(972)54-761-55-07</Tel>

                <NabBar $scrolled={scrolled} onClick={() => props.setOpen(false)}>
                    <a href="/">{t("header.nav.home")}</a>
                    <a href="/#portfolio">{t("header.nav.portfolio")}</a>
                    <a href="/#about">{t("header.nav.about_us")}</a>
                    <a href="/#contact">{t("header.nav.contact")}</a>
                    <a onClick={handleClickSurvey} href={address} target="_blank" rel="noopener noreferrer">
                        {t("header.nav.survey")}
                    </a>
                </NabBar>

                <Dropdown ref={dropdownRef} $show={isShowDropDown} $scrolled={scrolled}>
                    <button onClick={() => setShowDropDown((v) => !v)}>
                        <FontAwesomeIcon icon={faGlobe}/>
                        <p>{t("header.nav.lang")}</p>
                        <FontAwesomeIcon icon={faChevronDown}/>
                    </button>
                    <div>
                        {t("header.languages", {returnObjects: true}).map((v) => (
                            <p key={v.code} onClick={() => changeLanguage(v.code)}>
                                {v.nativeName}
                            </p>))}
                    </div>
                </Dropdown>
            </UL>
        </RightNavWrapper>);
};

export default RightNav;
