import React from "react";
import styled from "styled-components";
import { LOGO_BLUE } from "../../Utils/Constants";

const bp = {
    xl: 1200,
    lg: 1024,
    md: 820,
    sm: 600,
    xs: 380,
};

const Page = styled.section`
    min-height: 100svh;
    background: #f3f7f7;
    display: grid;
    place-items: center;
    padding: max(clamp(16px, 6vh, 48px)) max(clamp(12px, 4vw, 40px));

    #phone {
        direction: ltr;
        unicode-bidi: plaintext;
        text-align: start !important;
    }

    @media print {
        background: #fff;
        padding: 0;
    }
`;

const Sheet = styled.div`
    width: min(980px, 100%);
    background: #fff;
    box-shadow: 20px 20px 20px gray;
    padding: clamp(18px, 4vw, 40px);
    display: grid;
    grid-template-columns: 1fr 1.1fr;
    gap: clamp(18px, 3.6vw, 48px);

    @media (max-width: ${bp.lg}px) {
        grid-template-columns: 1fr;
        gap: 24px;
    }
    @media (max-width: ${bp.sm}px) {
        margin-top: 7vh;
        padding: clamp(16px, 5vw, 24px);
    }

    @media print {
        box-shadow: none;
        padding: 24px 32px;
    }
`;

const Left = styled.aside`
    display: grid;
    align-content: start;
    justify-items: start;
    gap: 14px;
    color: #2f3a48;

    @media (max-width: ${bp.lg}px) {
        justify-items: center;
        text-align: center;
    }
`;

const BrandSection = styled.div`
    display: grid;
    justify-items: center;
    gap: 10px;
`;

const Brand = styled.div`
    display: grid;
    gap: 8px;
    align-content: start;
    justify-items: center;
`;

const Logo = styled.img`
    width: clamp(84px, 13vw, 120px);
    height: auto;
    margin-bottom: 1vh;
`;

const Slogan = styled.p`
    margin: 0;
    font-weight: 700;
    letter-spacing: 0.12em;
    color: #5c6a79;
    text-transform: uppercase;
    font-size: clamp(10px, 1.2vw, 12px);
    line-height: 1.35;
`;

const ContactBig = styled.a`
    margin: 0;
    color: #2f3a48;
    font-size: clamp(16px, 2.4vw, 22px);
    font-weight: 700;
    letter-spacing: 0.02em;
    text-decoration: none;
    direction: ltr;
    unicode-bidi: plaintext;

    &:hover { text-decoration: underline; }
`;

const ContactSmall = styled.a`
    margin: 0;
    color: #5c6a79;
    font-size: clamp(14px, 2vw, 18px);
    font-weight: 500;
    text-decoration: none;
    direction: ltr;
    unicode-bidi: plaintext;

    &:hover { text-decoration: underline; }
`;

const Right = styled.main`
    color: #0f0f0f;
    display: grid;
    align-content: start;
    justify-content: start;
    gap: 10px;
    direction: rtl;

    @media (max-width: ${bp.lg}px) {
        gap: 8px;
    }
`;

const Title = styled.h2`
    margin: 0 0 8px 0;
    font-size: clamp(20px, 2.8vw, 30px);
    font-weight: 800;
    text-align: start;
`;

const Row = styled.div`
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 8px 14px;
    align-items: baseline;
    font-size: clamp(16px, 2.2vw, 20px);
    line-height: 1.45;
    text-align: start;
    word-break: break-word;

    b {
        font-weight: 800;
        color: #2f3a48;
        white-space: nowrap;
    }

    /* Мобильная компоновка: метка над значением */
    @media (max-width: ${bp.sm}px) {
        grid-template-columns: 1fr;
        align-items: start;

        b { margin-bottom: 2px; }
    }
`;

const Divider = styled.hr`
  border: none;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(0, 0, 0, 0.18), transparent);
  margin: 14px 0;

  @media (max-width: ${bp.sm}px) { margin: 10px 0; }
`;

export default function PublicRequisitesPage() {
    return (
        <Page aria-labelledby="req-title">
            <Sheet>
                <Left>
                    <BrandSection>
                        <Logo src={LOGO_BLUE} alt="Hexobee logo" />
                        <Brand>
                            <Slogan>
                                Multilingual websites <br />
                                that grow your business.
                            </Slogan>
                        </Brand>

                        <ContactBig href="tel:+972547615507">+972 54-761-55-07</ContactBig>
                        <ContactSmall href="https://hexobee.com" target="_blank" rel="noreferrer">
                            hexobee.com
                        </ContactSmall>
                        <Divider />
                    </BrandSection>
                </Left>

                <Right>
                    <Title id="req-title">פרטי חברה (ציבורי)</Title>

                    <Row>
                        <b>שם החברה :</b>
                        <span>TOPDEV</span>
                    </Row>

                    <Row>
                        <b>ח.פ (מספר עוסק) :</b>
                        <span>345083000</span>
                    </Row>

                    <Row>
                        <b>כתובת :</b>
                        <span>רחוב סיני 3, אשקלון, ישראל</span>
                    </Row>

                    <Row>
                        <b>טלפון :</b>
                        <span id="phone">
              <a href="tel:+972547615507">+972 54-761-55-07</a>
            </span>
                    </Row>

                    <Row>
                        <b>דוא״ל :</b>
                        <span>
              <a href="mailto:top.dev.aura@gmail.com">top.dev.aura@gmail.com</a>
            </span>
                    </Row>
                </Right>
            </Sheet>
        </Page>
    );
}
